(window.FREALLY_I18N = window.FREALLY_I18N || {})["vi"] = {"hero.headline":"<span class=\"hl-muted\">Vòng lặp của bạn. Cách phối của họ.</span> <span class=\"cycle\" data-cycle=\"hero.cycle\">Bản nhạc của bạn.</span>","hero.cycle":"Bản nhạc của bạn.|Stem của bạn.|MIDI của bạn.","hero.sub":"Biến một vòng lặp 8 ô nhịp thành một bản nhạc hoàn chỉnh, đã phối khí theo phong cách của bất kỳ nghệ sĩ, nhà sản xuất hay thể loại nào — được trình diễn trực tiếp trong DAW của bạn, rồi kéo ra dưới dạng stem âm thanh hoặc một mẫu bài hát MIDI. Miễn phí, ngoại tuyến và 100% không dùng AI.","hero.chipStandalone":"Ứng dụng độc lập","hero.chipWeb":"Ứng dụng web","what.title":"Đây là gì","what.p1":"Một vòng lặp nghe đã hoàn chỉnh ở ô nhịp 8 thì đến ô nhịp 64 vẫn chỉ là một vòng lặp. Biến nó thành một bản nhạc nghĩa là hàng giờ tắt tiếng, sao chép, cắt và tự động hóa — phần mở đầu, các điệp khúc, các đoạn ngắt quãng, các lần đổi beat — trước khi bạn nghe được ý tưởng đó có trụ vững hay không.","what.p2":"Freally Unloop phối nó cho bạn. Đặt nó trên track đang phát vòng lặp, chọn một nghệ sĩ, nhà sản xuất hoặc thể loại, rồi nhấn phát: Unloop trình diễn cả bản nhạc trên chính âm thanh của bạn, khớp nhịp với dự án, theo đúng cách mà cái tên đó phối khí.","what.p3":"Rồi bản nhạc là của bạn. Chỉnh sửa từng clip, giữ những gì bạn thích và tạo lại phần còn lại, rồi kết xuất nó — bản mix hoặc mỗi phần một tệp — để kéo thẳng vào các track của bạn.","how.title":"Cách hoạt động","how.loop.title":"Cho lặp lại.","how.loop.body":"8 ô nhịp của bạn lặp trong DAW — hoặc thả stem hay một vòng lặp MIDI vào ứng dụng độc lập hoặc ứng dụng web.","how.name.title":"Chọn một cái tên.","how.name.body":"Tìm trong 2.413 nghệ sĩ, nhà sản xuất và thể loại rồi chọn một chế độ: mỗi thể loại có thể được phối theo vài cách.","how.play.title":"Nhấn phát.","how.play.body":"Unloop trình diễn cả bản nhạc trên chính âm thanh của bạn — mở đầu, điệp khúc, ngắt quãng, cắt 808, dâng lắp bắp, dừng băng, đổi beat — khớp nhịp với dự án của bạn.","how.shape.title":"Nhào nặn.","how.shape.body":"Di chuyển, sao chép, tách và làm mờ dần clip, điều khiển fader, vẽ tự động hóa, khóa những gì bạn thích và tạo lại phần còn lại.","how.take.title":"Mang đi.","how.take.body":"Kéo bản nhạc đã phối ra dưới dạng WAV, AIFF, FLAC hoặc MP3 — bản mix hoặc stem — hoặc dưới dạng một mẫu bài hát MIDI nhiều track.","docs.language.title":"Ngôn ngữ","docs.language.p1":"Unloop có mười tám ngôn ngữ. Nó khởi động bằng ngôn ngữ của hệ thống; để chọn ngôn ngữ khác, hãy mở Cài đặt bằng biểu tượng bánh răng và chọn một ngôn ngữ.","ladder.title":"Con đường đến 1.0","ladder.intro":"Mỗi phiên bản một dòng. Đây là chính chiếc thang mà kế hoạch nội bộ đang theo — nếu một bên di chuyển, bên kia cũng di chuyển, và một cổng kiểm tra khi dựng sẽ đối chiếu chúng.","ladder.rung.v0.1.0":"Plugin (CLAP, VST3, AU) và ứng dụng độc lập tải được và cho âm thanh đi qua; khung trình chỉnh sửa, token thiết kế, 18 ngôn ngữ, mọi cổng kiểm tra chất lượng, CI cục bộ trên Windows và Linux, trình xác thực plugin, kiểm thử trên trình duyệt.","ladder.rung.v0.2.0":"Bất kỳ cái tên nào trong 2.413 nghệ sĩ, nhà sản xuất và thể loại đều trở thành một kế hoạch phối khí tất định, với vài chế độ cho mỗi thể loại.","ladder.rung.v0.3.0":"Một phiên bản plugin trên một beat đang lặp trình diễn trực tiếp cả bản nhạc — không tiếng click, độ trễ bằng không, đồng bộ với DAW của bạn.","ladder.rung.v0.4.0":"Mỗi phần một phiên bản plugin, được chỉ huy như một bản nhạc duy nhất, với bàn trộn đầy đủ.","ladder.rung.v0.5.0":"Thu, nghe thử ngay trong Unloop, kết xuất ra WAV/AIFF/FLAC/MP3, kéo ra ngoài, dự án vòng lặp và Thư viện vòng lặp — duyệt, nghe thử và cắt các vòng lặp của bạn, mở lại các dự án gần đây — sản phẩm hoàn chỉnh đầu tiên: MVP.","ladder.rung.v0.6.0":"Di chuyển, sao chép, tách và đổi độ dài clip; mờ dần, fader và tự động hóa; khóa và tạo lại; hoàn tác và làm lại không giới hạn; kệ bản phối và tệp .unarr; mọi thao tác chỉnh sửa từ bàn phím.","ladder.rung.v0.6.5":"Núm vặn, fader và nút bấm được dựng bằng Blender, năm giao diện ở bản sáng và tối, âm thanh giao diện và thanh tiêu đề tối — giống nhau trên mọi ứng dụng Freally.","ladder.rung.v0.7.0":"Âm thanh sang MIDI, nạp vòng lặp MIDI, mẫu bài hát MIDI, Bác sĩ velocity, kéo MIDI ra ngoài.","ladder.rung.v0.8.0":"Chế độ stem trong ứng dụng độc lập và ứng dụng web, khớp theo tempo, Bác sĩ vòng lặp.","ladder.rung.v0.9.0":"Re-Dream, hiệu ứng chuyển đoạn tổng hợp, đổi beat, Bác sĩ phối khí, mẫu, MIDI learn.","ladder.rung.v0.10.0":"Mọi thể loại với nhiều chế độ, hàng trăm nghệ sĩ và nhà sản xuất chủ lực, mọi cái tên đều được ánh xạ một cách trung thực.","ladder.rung.v1.0.0b":"Đủ tính năng: các trường hợp biên, trợ năng, 18 ngôn ngữ, ngân sách hiệu năng, trình cài đặt cho ba hệ điều hành.","ladder.rung.v1.0.0-rc":"Rà soát từ đầu đến cuối và sửa mọi lỗi, rồi thử thủ công trong các DAW thật trên mọi hệ điều hành sẵn có — cùng ứng dụng web hoàn chỉnh và trang này đã hoàn tất.","ladder.rung.v1.0.0":"Mở tải xuống, và ứng dụng web chính thức hoạt động.","ladder.rung.v1.1.0":"Chiều sâu biến tấu.","ladder.rung.v1.2.0":"Chiều sâu động tác.","ladder.rung.v1.3.0":"Phối khí có tính đến giọng hát.","ladder.rung.v1.4.0":"Trình diễn và DJ.","ladder.rung.v1.5.0":"Cầu nối Freally MIDI Master.","ladder.rung.v1.6.0":"Chiều sâu danh sách tên và bộ dữ liệu.","ladder.rung.v1.7.0":"Xuất tệp và khả năng tương tác.","ladder.rung.v1.8.0":"Chiều sâu quy trình làm việc và trợ năng.","ladder.rung.v1.9.0":"Tích hợp Freally.","ladder.note":"Một phiên bản hoàn tất đã được dựng và gắn thẻ. Đó không phải là bản tải xuống: chưa có, và sẽ không có cho đến 1.0.0.","honest.title":"Những điều mà hầu hết các trang web đặt ở cuối trang","honest.notes.title":"Nó phối nhạc của bạn; nó không viết nhạc","honest.notes.body":"Mọi âm thanh trong một bản nhạc đã phối đều đến từ vòng lặp của bạn, hoặc là một hiệu ứng chuyển đoạn Unloop tạo ra từ bộ dao động và tiếng ồn. Nó quyết định khi nào mỗi phần chơi và trình diễn các động tác trên phần đó, nhưng không bao giờ viết một nốt nhạc mới nào và không bao giờ thay đổi tệp vòng lặp trên ổ đĩa của bạn. Một đoạn fill mới, hay beat thứ hai cho một lần đổi beat, phải đến từ bạn.","honest.bands.title":"Một vòng lặp stereo được phối theo ba dải tần","honest.bands.body":"Khi chỉ có một vòng lặp stereo đã hoàn chỉnh để làm việc, Unloop điều khiển các dải trầm, trung và cao của nó, nên một động tác không thể tách tiếng snare ra khỏi giai điệu. Hãy đặt một phiên bản plugin trên track riêng của từng phần để dùng đầy đủ các động tác.","honest.styles.title":"Tên gọi chỉ mô tả phong cách","honest.styles.body":"Tên nghệ sĩ, nhà sản xuất và thể loại chỉ được dùng để mô tả phong cách âm nhạc. Freally Unloop không liên kết với, không được tán thành, tài trợ hay phê duyệt bởi bất kỳ nghệ sĩ, nhà sản xuất, hãng đĩa hay chủ sở hữu quyền nào, và không bao giờ tái tạo cách phối của một bài hát cụ thể.","honest.styles.link":"Đọc toàn bộ tuyên bố miễn trừ trách nhiệm (bằng tiếng Anh)","honest.hands.title":"Chưa được thử thủ công trong mọi DAW","honest.hands.body":"Unloop được dựng và kiểm tra bằng các cổng kiểm tra tự động trên Windows, Linux và macOS. Việc thử thủ công trong các DAW thật, trên mọi hệ điều hành, là việc của bản ứng viên phát hành, trước 1.0.0.","honest.downloads.title":"Chưa có bản tải xuống nào trước 1.0.0","honest.downloads.body":"Trang này không có bản beta, không có bản dựng xem trước, không có quyền truy cập sớm. Một công cụ phối khí chỉ chạy được một nửa còn tệ hơn một công cụ chưa ra đời.","honest.network.title":"Nó không bao giờ lên mạng","honest.network.body":"Plugin và ứng dụng độc lập hoàn toàn không chứa mã mạng nào, và một cổng kiểm tra khi dựng sẽ thất bại nếu có mã như vậy được thêm vào. Một phiên bản sau này có thể thêm một tính năng kiểm tra cập nhật, mặc định tắt trừ khi bạn tự bật lên, được chạy bởi một chương trình riêng biệt.","site.tagline":"Mỗi vòng lặp là một bản nhạc đang chờ thành hình.","footer.licence":"Phần mềm độc quyền — Bảo lưu mọi quyền. © Mike Weaver. Hiện miễn phí sử dụng; các phiên bản sau này có thể được bán. Không phải mã nguồn mở.","footer.yours":"Âm nhạc bạn tạo ra với Unloop là của bạn, trong phạm vi những vòng lặp bạn đã phối là thứ bạn có quyền sử dụng, không cần trả tiền bản quyền và không cần ghi công.","featuresPage.lead":"Freally Unloop biến một vòng lặp 8 ô nhịp thành một bản nhạc hoàn chỉnh, đã phối khí theo phong cách của bất kỳ cái tên nào trong 2.413 nghệ sĩ, nhà sản xuất và thể loại — được trình diễn trên chính âm thanh của bạn, trực tiếp trong DAW, rồi kéo ra dưới dạng stem âm thanh hoặc một mẫu bài hát MIDI.","featuresPage.version":"Trang này mô tả Freally Unloop phiên bản 1.0: mọi thứ trên đây đều có trong 1.0, và không có gì dự kiến cho sau 1.0 được đưa vào.","featuresPage.numbers.names":"nghệ sĩ, nhà sản xuất và thể loại để phối theo","featuresPage.numbers.artists":"nghệ sĩ","featuresPage.numbers.producers":"nhà sản xuất","featuresPage.numbers.genres":"thể loại","featuresPage.numbers.flagships":"phong cách chủ lực, đến tận động tác đặc trưng","featuresPage.numbers.lanes":"làn tự động hóa cho mỗi phần","featuresPage.numbers.formats":"định dạng tệp xuất ra: WAV, AIFF, FLAC, MP3 và MIDI","featuresPage.numbers.latency":"sample độ trễ thêm vào","featuresPage.numbers.systems":"hệ điều hành: Windows, macOS và Linux","featuresPage.numbers.languages":"ngôn ngữ","featuresPage.numbers.ai":"mô hình AI","featuresPage.numbers.price":"giá hiện nay","featuresPage.free.title":"Hiện miễn phí","featuresPage.free.body":"Mọi thứ Unloop làm hiện nay đều miễn phí, cho tất cả mọi người: không gói trả phí, không thuê bao, không tài khoản, không mã kích hoạt, không quảng cáo và không bản dùng thử nào hết hạn. Các bản phối, âm thanh, stem và MIDI bạn tạo ra với nó là của bạn, trong phạm vi những vòng lặp bạn đã phối là thứ bạn có quyền sử dụng.","featuresPage.cards.title":"Phiên bản 1.0 làm được gì","featuresPage.cards.search.title":"Tìm một cái tên, không phải một thể loại","featuresPage.cards.search.body":"2.413 nghệ sĩ, nhà sản xuất và thể loại trong một ô tìm kiếm, tìm được cả qua tên gọi khác lẫn lỗi gõ. Trước khi bạn nhấn bất cứ thứ gì, một tấm thẻ cho biết cái tên đó làm gì: các cấu trúc bài hát, các cách phối, độ dài các đoạn và những động tác đặc trưng của nó.","featuresPage.cards.modes.title":"Không chỉ một mẫu cho mỗi thể loại","featuresPage.cards.modes.body":"Một thể loại được phối theo vài cách — bản radio, bản mixtape, bản club, đổi beat, tối giản — trừ khi nó thật sự chỉ có một cách, và khi đó thẻ của nó nói rõ lý do. Nghệ sĩ và nhà sản xuất có thêm những cách riêng của họ, và mỗi lần nhấn là một hạt giống mới mà bạn có thể giữ lại rồi dán vào để lấy lại đúng bản phối đó.","featuresPage.cards.live.title":"Cả bản nhạc, trình diễn trực tiếp","featuresPage.cards.live.body":"Nhấn phát và Unloop trình diễn bản nhạc trên chính âm thanh của bạn, khớp nhịp với dự án: mở đầu, điệp khúc, ngắt quãng, cắt 808, quét bộ lọc, dâng lắp bắp, dừng băng, nửa nhịp và đổi beat. Không động tác nào gây tiếng click, và không động tác nào thêm độ trễ.","featuresPage.cards.pattern.title":"Ngay cả trên một vòng lặp không bao giờ tiến lên","featuresPage.cards.pattern.body":"Chế độ pattern của FL Studio và chế độ xem session của Ableton lặp lại mà không di chuyển vị trí bài hát. Unloop tự đếm số vòng lặp, nên cả bản nhạc vẫn phát trên 8 ô nhịp cứ quay vòng đó.","featuresPage.cards.parts.title":"Một vòng lặp, hoặc từng phần","featuresPage.cards.parts.body":"Một vòng lặp stereo là đủ: Unloop phối nó theo các dải trầm, trung và cao. Hoặc đặt một phiên bản plugin trên track của từng phần, và một trong số đó sẽ chỉ huy tất cả như một bản nhạc duy nhất, với cả một bàn trộn đầy đủ fader và đèn báo.","featuresPage.cards.timeline.title":"Dòng thời gian là của bạn","featuresPage.cards.timeline.body":"Di chuyển, sao chép, tách, đổi độ dài và làm mờ dần mọi clip với kiểu mờ dần ba tay nắm; điều khiển fader của clip, của phần và fader tổng; vẽ tự động hóa trên 12 làn cho mỗi phần; sắp xếp lại các đoạn; khóa những gì bạn thích và tạo lại phần còn lại. Hoàn tác không giới hạn, và tính năng tự động lưu vẫn giữ được dữ liệu sau sự cố treo máy.","featuresPage.cards.take.title":"Nghe thử, rồi mang đi","featuresPage.cards.take.body":"Nghe thử bản phối ngay trong Unloop khi DAW đang dừng. Kết xuất ra WAV, AIFF, FLAC hoặc MP3, bản mix hoặc mỗi phần một stem, và kéo cả bài, một phần hay một đoạn thẳng vào các track của bạn. Mỗi tệp đều có một biên nhận đi kèm.","featuresPage.cards.midi.title":"Âm thanh hay MIDI, chỉ một công tắc","featuresPage.cards.midi.body":"Chuyển sang MIDI và chính bản phối đó trở thành một mẫu bài hát MIDI nhiều track, đọc từ các nốt trong vòng lặp của bạn, kèm dấu mốc cho từng đoạn. Bác sĩ velocity cho mỗi phần đúng kiểu velocity: nốt nhấn và nốt ghost cho trống, 808 đều đặn, hợp âm đồng đều.","featuresPage.cards.shelf.title":"Một vòng lặp, nhiều bản phối","featuresPage.cards.shelf.body":"Mỗi vòng lặp được lưu một lần, thành dự án riêng, kèm một kệ các bản phối có tên: chuyển giữa chúng ở ô nhịp kế tiếp, so sánh hai bản bất kỳ, và mang một bản sang vòng lặp khác dưới dạng tệp. Thư viện vòng lặp chứa mọi vòng lặp bạn có, sẵn sàng để nghe thử.","featuresPage.cards.standalone.title":"Một ứng dụng độc lập và một ứng dụng web","featuresPage.cards.standalone.body":"Thả tối đa tám stem hoặc tệp MIDI và phối chúng mà không cần DAW. Khi không có DAW để theo, Unloop gợi ý nhịp độ của nghệ sĩ và có thể kéo giãn vòng lặp của bạn theo nhịp độ đó; Bác sĩ vòng lặp tìm ra tiếng click ở điểm nối, hiện tượng clipping và nhịp độ không khớp.","featuresPage.cards.redream.title":"Re-Dream và Bác sĩ phối khí","featuresPage.cards.redream.body":"Re-Dream đưa ra ba biến thể mới cho bản phối bạn đang có, vẫn giữ nguyên bố cục của nó. Thêm hiệu ứng dâng và cú đập tổng hợp, tag nhà sản xuất của riêng bạn và đổi beat, rồi để Bác sĩ phối khí chỉ ra một điệp khúc đến quá muộn hay một đoạn chẳng bao giờ thay đổi, kèm cách sửa.","featuresPage.cards.offline.title":"Ngoại tuyến, riêng tư, không AI","featuresPage.cards.offline.body":"Không tài khoản, không đo lường từ xa và không mô hình: một bộ lập kế hoạch dựa trên quy tắc cùng xử lý tín hiệu cổ điển, được một cổng kiểm tra khi dựng xác minh. Plugin và ứng dụng độc lập không bao giờ kết nối mạng; ngoại lệ duy nhất là tính năng kiểm tra cập nhật, luôn tắt trừ khi bạn bật lên, và do một chương trình riêng chạy.","featuresPage.compare.title":"Đặt cạnh các công cụ thương mại","featuresPage.compare.intro":"Freally Unloop 1.0 đặt cạnh năm sản phẩm đang được bán hiện nay có thể phối một vòng lặp, tạo biến thể cho nó hoặc viết trọn bài hát: ArrangerKing (một plugin phối khí), Loopmix (một plugin remix vòng lặp), Songen (một ứng dụng làm beat), và Suno cùng SOUNDRAW (các trình tạo bài hát bằng AI). Mỗi ô của các sản phẩm khác đều lấy từ chính các trang của nhà sản xuất, được kiểm tra vào ngày 1 và 2 tháng 10 năm 2026, và giá tính bằng đô la Mỹ trước thuế, theo niêm yết ngày 2 tháng 10 năm 2026.","featuresPage.compare.feature":"Tính năng","featuresPage.compare.row.price":"Giá (USD, tháng 10 năm 2026)","featuresPage.compare.freeToday":"Hiện miễn phí","featuresPage.compare.price.songen":"Gói miễn phí; Premium $89,99/năm","featuresPage.compare.price.suno":"Gói miễn phí; Pro $10 và Premier $30/tháng","featuresPage.compare.price.soundraw":"Từ $16,99/tháng; stem từ $35,99","featuresPage.compare.row.yourLoop":"Biến chính vòng lặp của bạn thành trọn một bài hát, không viết thêm nhạc mới","featuresPage.compare.legend.yes":"có","featuresPage.compare.legend.partly":"một phần","featuresPage.compare.note.setMutes":"bạn tự đặt từng chỗ tắt tiếng","featuresPage.compare.note.variations":"biến thể vòng lặp","featuresPage.compare.legend.no":"không","featuresPage.compare.note.writesOwn":"tự viết nhạc riêng","featuresPage.compare.note.writesNew":"viết nhạc mới","featuresPage.compare.row.styleOf":"Phối theo phong cách của nghệ sĩ hay nhà sản xuất bạn chọn","featuresPage.compare.note.names":"2.340 cái tên","featuresPage.compare.note.genreTemplates":"mẫu theo thể loại","featuresPage.compare.note.genres":"thể loại","featuresPage.compare.note.nameStops":"nhập tên có thể bị chặn tạo bài","featuresPage.compare.note.genresMoods":"thể loại và tâm trạng","featuresPage.compare.row.moves":"Động tác trình diễn trên chính âm thanh của bạn: cắt 808, dâng lắp bắp, dừng băng","featuresPage.compare.note.mutesOnly":"chỉ tắt tiếng","featuresPage.compare.note.gateReverse":"gate, đảo ngược, cao độ","featuresPage.compare.row.edit":"Chỉnh được mọi clip, mờ dần, fader và làn tự động hóa","featuresPage.compare.note.partsMutes":"phần và tắt tiếng","featuresPage.compare.note.arrangementNotes":"bản phối và nốt nhạc","featuresPage.compare.note.premierStudio":"Premier, trong Studio","featuresPage.compare.note.muteSolo":"tắt tiếng, solo, cường độ","featuresPage.compare.row.stems":"Xuất stem âm thanh","featuresPage.compare.note.ofLoop":"của một vòng lặp","featuresPage.compare.note.paidPlans":"các gói trả phí","featuresPage.compare.note.artistPro":"từ Artist Pro trở lên","featuresPage.compare.row.midi":"Bài hát dưới dạng tệp MIDI","featuresPage.compare.note.fromYourLoop":"từ chính vòng lặp của bạn","featuresPage.compare.note.guideTracks":"chỉ track hướng dẫn","featuresPage.compare.row.plugin":"Plugin trong DAW của bạn","featuresPage.compare.row.systems":"Chạy gốc trên Windows, macOS và Linux","featuresPage.compare.note.wine":"Linux chỉ qua Wine","featuresPage.compare.note.browser":"chạy trong trình duyệt","featuresPage.compare.row.offline":"Hoạt động ngoại tuyến","featuresPage.compare.legend.unknown":"chưa xác minh","featuresPage.compare.row.account":"Không tài khoản, không đo lường từ xa","featuresPage.compare.note.usageData":"gửi dữ liệu sử dụng","featuresPage.compare.note.account":"cần tài khoản","featuresPage.compare.row.noAi":"Hoàn toàn không AI","featuresPage.compare.note.buildGate":"cổng kiểm tra khi dựng xác minh","featuresPage.compare.note.ownAi":"dùng AI riêng","featuresPage.compare.summaryTitle":"Tóm lại","featuresPage.compare.summary":"Nói ngắn gọn: chỉ Unloop biến chính vòng lặp của bạn thành trọn một bản nhạc, theo phong cách của nghệ sĩ hay nhà sản xuất bạn chọn, với các động tác được trình diễn trên chính âm thanh của bạn. Đây là sản phẩm duy nhất chạy gốc trên Linux cũng như Windows và macOS, và là sản phẩm duy nhất hoạt động ngoại tuyến mà không cần tài khoản, không đo lường từ xa và không AI.","featuresPage.compare.theyWinTitle":"Họ hơn ở đâu","featuresPage.compare.theyWin":"Những điểm họ hơn: Suno, SOUNDRAW và Songen viết nhạc mới cho bạn — điều mà Unloop cố ý không bao giờ làm. Loopmix cắt lát và sắp xếp lại bên trong một vòng lặp thay vì phối nó thành một bài hát, và nó còn là plugin AAX cho Pro Tools, điều mà Unloop 1.0 không có.","featuresPage.compare.asOf":"Cột của Unloop là phiên bản 1.0, hiện chưa ra mắt, và giá của nó là giá hiện nay: Unloop hiện miễn phí, và các phiên bản sau này có thể được bán. Các sản phẩm khác cũng thay đổi; bảng này cập nhật đến ngày 2 tháng 10 năm 2026. Tên sản phẩm là nhãn hiệu của chủ sở hữu tương ứng, và Freally Unloop không liên kết với bất kỳ bên nào trong số đó.","featuresPage.why.title":"Vì sao nó được xây dựng như vậy","featuresPage.why.sound.title":"Âm thanh của bạn, được phối — không bao giờ bị thay thế","featuresPage.why.sound.body":"Mọi âm thanh trong một bản nhạc đã phối đều đến từ vòng lặp của bạn, hoặc là một hiệu ứng chuyển đoạn Unloop tạo ra từ bộ dao động và tiếng ồn. Nó không bao giờ viết một nốt nhạc mới nào vào bài hát của bạn, và không bao giờ thay đổi tệp vòng lặp trên ổ đĩa của bạn.","featuresPage.why.rules.title":"Những quy tắc bạn đọc được","featuresPage.why.rules.body":"Một bộ lập kế hoạch đọc dữ liệu phối khí đã được nghiên cứu cho từng nghệ sĩ, nhà sản xuất và thể loại, rồi quyết định mọi đoạn và động tác trước khi một âm thanh nào vang lên. Cùng vòng lặp, cái tên, chế độ và hạt giống sẽ cho cùng một bản phối hôm nay và cả năm năm sau — nên hạt giống bạn gửi cho người cộng tác sẽ phát cho họ nghe đúng những gì bạn đã nghe.","featuresPage.why.views.title":"Hai góc nhìn, một sự thật","featuresPage.why.views.body":"Âm thanh và mẫu bài hát MIDI được dựng từ cùng một kế hoạch, và mọi chỉnh sửa đều đến được cả hai. Khi MIDI không thể diễn đạt điều một động tác đã làm — như cú tụt cao độ của dừng băng — động tác đó được đánh dấu là chỉ có ở âm thanh thay vì lặng lẽ bị bỏ đi.","featuresPage.why.local.title":"Mọi thứ ở lại trên máy của bạn","featuresPage.why.local.body":"Không tài khoản, không đo lường từ xa, không đám mây. Vòng lặp và bản nhạc của bạn không bao giờ rời khỏi máy tính, và một cổng kiểm tra khi dựng sẽ báo lỗi nếu mã mạng lọt vào plugin hay ứng dụng độc lập. Ứng dụng web chỉ tải một lần, sau đó hoạt động ngoại tuyến và không tải lên thứ gì.","featuresPage.why.tempo.title":"Nó đi theo DAW của bạn","featuresPage.why.tempo.body":"Plugin luôn phát ở nhịp độ của dự án và không bao giờ thay đổi nó. Khi nghệ sĩ hay nhà sản xuất bạn chọn làm việc ở một nhịp độ khác, Unloop gợi ý nhịp độ đó, và coi nửa nhịp hay gấp đôi nhịp cũng là khớp. Trong ứng dụng độc lập và ứng dụng web, nó có thể kéo giãn vòng lặp của bạn theo nhịp độ của họ.","featuresPage.why.styles.title":"Phong cách, không bao giờ là bài hát","featuresPage.why.styles.body":"Một cái tên chỉ mô tả cách một người phối khí, không hơn. Unloop không bao giờ tái tạo cách phối của một bài hát cụ thể, và không đưa các cái tên vào tên tệp của bạn trừ khi bạn tự thêm vào.","featuresPage.coming.title":"Những gì vẫn còn phía trước","featuresPage.coming.intro":"Nói thẳng ra, vì một danh sách tính năng che giấu chỗ còn thiếu thì không đáng đọc. Trang này mô tả phiên bản 1.0, và Unloop được xây dựng từng nấc một, nên không phải mọi thứ trên đây đều đã làm xong. Mỗi nấc trên con đường đến 1.0 đều được đánh dấu trạng thái.","featuresPage.limits.title":"Những gì 1.0 không làm","featuresPage.limits.newMusic":"Nó không viết nhạc mới. Một đoạn fill mới, hay pattern thứ hai cho một lần đổi beat, phải đến từ bạn: Unloop phối những gì có trong vòng lặp của bạn và chỉ thêm các hiệu ứng chuyển đoạn do nó tổng hợp.","featuresPage.limits.songs":"Nó không tái tạo cách phối của một bài hát nổi tiếng, và sẽ không bao giờ làm vậy.","featuresPage.limits.bands":"Một vòng lặp stereo được phối theo ba dải tần, nên một động tác không thể tách tiếng snare ra khỏi giai điệu. Hãy cho mỗi phần một track riêng để dùng đầy đủ các động tác; khi kết xuất, việc tách phần gõ và phần hòa âm sẽ giúp ích, và Unloop nói rõ đó chỉ là ước lượng.","featuresPage.limits.midi":"Phần MIDI chuyển từ âm thanh của nó nói rõ những gì nó không làm được: không tạo giai điệu đối từ âm thanh, hợp âm được ghi đơn giản, và một dòng giọng hát sẽ bị bỏ qua thay vì đoán mò.","featuresPage.limits.daw":"Nó là công cụ phối khí, không phải DAW: không thu âm, không chạy plugin khác, và không có bàn trộn nào ngoài fader của từng phần và fader tổng.","featuresPage.limits.aax":"Nó không phải plugin Pro Tools (AAX).","featuresPage.coming.downloads":"Chưa có bản tải xuống nào trước phiên bản 1.0, và trang này cũng không có.","docs.intro":"Hướng dẫn này mô tả phiên bản 0.6.0, phiên bản đã được dựng hiện nay. Khi một điều trên trang Tính năng chỉ có ở phiên bản sau, hướng dẫn sẽ nói rõ là phiên bản nào.","docs.start.title":"Bắt đầu","docs.agreement.title":"Thỏa thuận cấp phép","docs.window.title":"Cửa sổ","docs.name.title":"Chọn một cái tên","docs.generate.title":"Tạo, chế độ và hạt giống","docs.tempo.title":"Nhịp độ và đồng hồ","docs.parts.title":"Một vòng lặp, hoặc từng phần","docs.capture.title":"Thu và nghe thử","docs.print.title":"Kết xuất, kéo thả và biên nhận","docs.projects.title":"Dự án vòng lặp và Thư viện vòng lặp","docs.timeline.title":"Chỉnh sửa dòng thời gian","docs.fades.title":"Mờ dần và fader","docs.automation.title":"Tự động hóa","docs.sections.title":"Các đoạn","docs.reroll.title":"Khóa, tạo lại và tự đặt động tác","docs.history.title":"Hoàn tác, làm lại và tự động lưu","docs.shelf.title":"Nhiều bản phối trên một vòng lặp","docs.keys.title":"Phím tắt","docs.privacy.title":"Quyền riêng tư và mạng","docs.limits.title":"Hạn chế đã biết","docs.start.p1":"Freally Unloop chạy bên trong DAW của bạn dưới dạng plugin CLAP hoặc VST3, hoặc AU trên macOS, và chạy riêng dưới dạng ứng dụng độc lập. Hãy đặt nó trên track đang phát vòng lặp của bạn: cho đến khi bạn nhấn Tạo, nó cho âm thanh của track đi qua đúng như khi đi vào, nên bạn có thể yên tâm để nó ở đó.","docs.start.p2":"Phiên bản 0.6.0 được xây dựng để dùng trong DAW, với âm thanh. MIDI sẽ có trong phiên bản 0.7.0; việc phối các stem thả vào ứng dụng độc lập, cùng ứng dụng web, sẽ có trong phiên bản 0.8.0.","docs.start.p3":"Chưa có bản tải xuống nào trước phiên bản 1.0.0, và mã nguồn là riêng tư.","docs.agreement.p1":"Lần đầu mở, Unloop hiển thị Thỏa thuận cấp phép người dùng cuối, được viết bằng tiếng Anh. Hãy đọc đến cuối, khi đó nút Đồng ý mới dùng được.","docs.agreement.p2":"Nếu bạn từ chối, Unloop sẽ tạm dừng: không có gì được phối, và âm thanh của bạn vẫn đi qua mà không thay đổi. Hãy chọn Đọc lại bất cứ khi nào bạn sẵn sàng. Câu trả lời của bạn được lưu trên máy tính, áp dụng cho mọi bản Unloop trên máy đó.","docs.window.p1":"Dọc phía trên là menu dự án vòng lặp (nút thư mục), menu Bản phối, ô tìm kiếm, chế độ, cùng Hoàn tác và Làm lại; bên phải là nhịp độ, đồng hồ và Cài đặt (biểu tượng bánh răng). Ở giữa là bản đồ phối khí: các đoạn của bản nhạc, một làn cho mỗi phần, và các động tác. Dọc phía dưới là bàn trộn: Tạo, một dải kênh cho mỗi phần, phần master và hạt giống.","docs.window.p2":"Cài đặt chứa ngôn ngữ, giao diện — Hệ thống, Tối hoặc Sáng — và danh sách phím tắt.","docs.name.p1":"Gõ vào ô tìm kiếm để tìm bất kỳ cái tên nào trong 2.413 nghệ sĩ, nhà sản xuất và thể loại. Tên gọi khác và cách gõ gần đúng cũng tìm ra được, và các chữ như Ø, ß và Ł được quy về chữ cái thường gặp, nên \"mo\" sẽ tìm ra MØ. Khi ô tìm kiếm trống, nó gợi ý các cái tên bạn dùng gần đây và các mô hình chủ lực. Dùng phím mũi tên và Enter, hoặc nhấn chuột.","docs.name.p2":"Mỗi cái tên có một thẻ mô hình: các chế độ nó dùng để phối và tần suất mỗi chế độ được rút ra, các cấu trúc bài hát điển hình, các động tác đặc trưng, những phần nó điều khiển, nguồn gốc dữ liệu và độ tin cậy của dữ liệu đó. Một cái tên có ít dữ liệu riêng sẽ kế thừa từ thể loại của nó, và thẻ hiển thị chuỗi kế thừa.","docs.generate.p1":"Nhấn Tạo và Unloop lên kế hoạch cho cả bản nhạc theo cái tên bạn đã chọn: mọi đoạn, những phần nào chơi trong mỗi đoạn, và mọi động tác. Hãy chọn một chế độ trước — Bản radio, Bản mixtape, Bản club / DJ, Đổi beat, Tối giản và nhiều chế độ khác, tùy theo cái tên — hoặc để ở Chế độ bất kỳ và Unloop sẽ tự rút một chế độ.","docs.generate.p2":"Mỗi kế hoạch có một hạt giống gồm 16 chữ số thập lục phân, hiển thị trên bàn trộn, và mỗi lần nhấn Tạo sẽ rút ra một hạt giống mới. Cùng vòng lặp, cái tên, chế độ và hạt giống luôn cho ra cùng một bản phối: hãy sao chép hạt giống để giữ một bản phối hoặc gửi cho người cộng tác, và dán nó vào để lấy lại bản phối đó.","docs.tempo.p1":"Trong DAW, Unloop luôn phát ở nhịp độ của dự án và không bao giờ thay đổi nó. Nhãn nhịp độ cho biết nhịp độ của bạn có nằm trong khoảng mà cái tên đó thường dùng hay không — coi nửa nhịp và gấp đôi nhịp cũng là khớp — và nếu không, nên đặt DAW ở nhịp độ nào, kèm một nút để sao chép nhịp độ đó.","docs.tempo.p2":"Unloop cần biết vòng lặp của bạn dài bao nhiêu: nó sẽ hỏi, và coi là 8 ô nhịp cho đến khi bạn trả lời. Đồng hồ đi theo vị trí bài hát của DAW, hoặc tự đếm số vòng lặp khi vị trí không di chuyển — chế độ pattern của FL Studio, hay chế độ xem session của Ableton Live — nên cả bản nhạc vẫn phát trên một vòng lặp cứ quay vòng. Tự động sẽ quyết định thay bạn; chọn Bài hoặc Vòng lặp để tự quyết định.","docs.parts.p1":"Trên một track duy nhất chứa một vòng lặp stereo đã hoàn chỉnh, Unloop phối nó theo ba dải tần — trầm, trung và cao — và bản đồ ghi rõ điều đó.","docs.parts.p2":"Để dùng đầy đủ các động tác, hãy đặt một phiên bản plugin trên track của từng phần và giao cho mỗi phiên bản một vai trò: trống, bass, giai điệu, hợp âm, v.v. Unloop gợi ý vai trò dựa trên tên track. Các phiên bản trên cùng một kênh cùng trình diễn một bản nhạc: phiên bản đầu tiên làm nhạc trưởng, mọi phiên bản khác theo kế hoạch của nó chính xác đến từng sample và chỉ phát các động tác của phần mình. Bàn trộn hiển thị một dải kênh cho mỗi phiên bản, với fader và đèn báo riêng.","docs.parts.p3":"Khi DAW chạy plugin trong các tiến trình riêng, các phiên bản gặp nhau qua một tệp dùng chung trên máy tính của bạn, không bao giờ qua mạng. Nếu một kênh đã có kế hoạch của một dự án khác, Unloop sẽ báo và đề xuất một kênh khác.","docs.capture.p1":"Sau khi nhấn Tạo, mỗi phiên bản plugin thu một chu kỳ của vòng lặp — phần nhạc đi vào track của nó, không bao giờ là đầu ra của chính nó — và từ đó trở đi phát bản nhạc từ bộ nhớ. Nhãn TRỰC TIẾP / ĐÃ THU cho biết trạng thái hiện tại, kèm Thu lại và Quên bản thu. Không thể thu một vòng lặp dài hơn 64 giây, và nếu dừng, nhảy vị trí hay đổi nhịp độ trong lúc thu thì việc thu sẽ bắt đầu lại ở lần phát tiếp theo.","docs.capture.p2":"Nếu vòng lặp đang đi vào không còn là vòng lặp đã thu, nhãn sẽ hỏi: Vòng lặp đã đổi — thu lại? Không có gì bị thay thế khi nó đang phát; thu lại hay không là do bạn nhấn.","docs.capture.p3":"Khi DAW đang dừng, các nút phát, tạm dừng, dừng và lặp trong phần master — hoặc phím cách — cho bạn nghe thử cả bản nhạc ngay trong Unloop, mọi phiên bản plugin trên kênh cùng phát. Nhấn vào thước của bản đồ để nhảy tới, hoặc lặp một đoạn. Nhấn phát trong DAW và DAW sẽ tiếp quản ngay lập tức.","docs.print.p1":"Nút KẾT XUẤT trong phần master mở hộp thoại Kết xuất & xuất tệp. Chọn thứ cần kết xuất — bản mix, các stem, bất kỳ phần nào, một đoạn hay cả bản nhạc — và định dạng: WAV (16 bit, 24 bit hoặc 32 bit dấu phẩy động), AIFF, FLAC hoặc MP3, ở tần số lấy mẫu như khi thu hoặc một tần số bạn chọn. Tệp được kết xuất qua chính đoạn mã phát trực tiếp, nên tệp chính là những gì bạn đã nghe. Hủy sẽ không để lại gì.","docs.print.p2":"Bạn có thể dither khi giảm độ sâu bit, đặt một bộ giới hạn an toàn ở −1 dBTP trên bản mix, và ghi biên nhận. Tên tệp được tạo từ một mẫu bạn có thể chỉnh sửa, và theo mặc định không tên tệp nào chứa tên nghệ sĩ hay nhà sản xuất. Khi xuất xong, đồng hồ kết xuất hiển thị mức đỉnh, đỉnh thực và độ to của bản mix.","docs.print.p3":"Để bỏ qua hộp thoại, hãy dùng khay kéo: kéo bản mix, các stem, một phần hoặc một đoạn thẳng vào các track của bạn. Các tệp được kết xuất trước khi bắt đầu kéo, mặc định là WAV 24 bit.","docs.print.p4":"Một biên nhận — một tệp .unloop-receipt.json nhỏ — đi kèm mỗi lần xuất và mỗi lần kéo. Nó ghi các phiên bản, cái tên, chế độ và hạt giống, cùng các dấu vân tay cần thiết để tạo lại đúng bản nhạc đó. Biên nhận được bật theo mặc định; bạn có thể tắt chúng trong hộp thoại.","docs.projects.p1":"Lưu dự án vòng lặp… trong menu dự án vòng lặp (nút thư mục) lưu vòng lặp — các phần của nó dưới dạng FLAC 24 bit — cùng mọi bản phối trên nó, thành một tệp .unloop duy nhất. Mở dự án vòng lặp… khôi phục nó y nguyên. Việc lưu không bao giờ ghi đè lên tệp: một tên đã có sẽ được thêm (2).","docs.projects.p2":"Thư viện vòng lặp, trong cùng menu đó, liệt kê mọi dự án .unloop và mọi tệp WAV, AIFF, FLAC, MP3 và MIDI trong các thư mục bạn thêm vào, kèm số ô nhịp, nhịp độ, thẻ và số lần đã được phối. Bạn có thể tìm kiếm và lọc; nhấn vào một vòng lặp để nghe nó ngay trong Unloop (phím mũi tên để duyệt danh sách, Esc để dừng), và Phối khí nó khi nó đúng là một vòng lặp. Nó chỉ đọc các thư mục của bạn, không bao giờ làm gì khác. Vòng lặp MIDI đã được liệt kê từ bây giờ và sẽ phối được từ phiên bản 0.7.0.","docs.projects.p3":"Tạo vòng lặp từ tệp dài hơn… cắt một vòng lặp ra khỏi một bản ghi âm dài hơn: chọn ô nhịp bắt đầu, độ dài 1, 2, 4, 8 hoặc 16 ô nhịp và nhịp độ, nghe đoạn cắt lặp đi lặp lại, rồi nhấn Phối khí để biến nó thành một dự án vòng lặp mới. Bản thân tệp không bao giờ bị thay đổi.","docs.projects.p4":"Dự án gần đây liệt kê những gì bạn đã mở hoặc lưu, mới nhất ở trên cùng. Một dự án đã bị di chuyển sẽ hiện là bị thiếu, và Xóa khỏi danh sách chỉ gỡ dòng đó đi — không bao giờ xóa tệp.","docs.timeline.p1":"Bạn có thể chỉnh sửa mọi clip trên bản đồ. Nhấn để chọn một clip, Shift-nhấp hoặc kéo một khung chọn để chọn thêm, hoặc nhấn Ctrl/Cmd+A để chọn tất cả. Kéo một clip để di chuyển nó theo lưới (giữ Alt để di chuyển tự do), kéo một cạnh để đổi độ dài — vòng lặp sẽ lặp lại khi vượt quá độ dài của nó — và Alt-kéo bên trong clip để trượt nội dung. Phím S tách clip tại con trỏ chỉnh sửa.","docs.timeline.p2":"Menu của clip — nhấp chuột phải, Shift+F10 hoặc phím menu — chứa Cắt, Sao chép, Dán, Nhân bản phía sau, Sao chép tại chỗ, Xóa, Tách tại con trỏ, Đảo ngược, Khóa, Về lại kế hoạch, Màu và Đổi tên. Khi bạn dán một clip vào làn mà phần của nó không thể đặt lên, Unloop sẽ đề xuất những làn phù hợp.","docs.timeline.p3":"Bám lưới theo ô nhịp, phách, nốt móc đơn hay nốt móc kép, các liên ba của chúng, hoặc tắt; phóng to, thu nhỏ, hoặc vừa khung cả bản nhạc. Ở chỗ các clip gặp nhau, Unloop tạo crossfade giữa chúng trong 3 ms, và khi tắt bám lưới, mỗi cạnh sẽ rơi vào điểm giao cắt không gần nhất của vòng lặp, nên không thao tác chỉnh sửa nào gây tiếng click.","docs.fades.p1":"Mỗi đầu của một clip có ba tay nắm mờ dần, như trong chế độ xem phối khí bài hát của Freally MIDI Master: độ dài nằm ở cạnh trên của clip và đường cong nằm ngay trên đoạn mờ dần. Chúng không bao giờ chồng chéo nhau, dù clip dài bao nhiêu.","docs.fades.p2":"Kéo tay nắm mức của clip từ −∞ đến +6 dB — giữ Shift để chỉnh từng bước nhỏ, nhấp đúp để về 0 dB. Bàn trộn có một fader cho mỗi phần và một fader tổng. Mọi thay đổi đều nghe được ngay khi bạn kéo, và thành một bước hoàn tác khi bạn thả tay.","docs.automation.p1":"Mở Tự động hóa, chọn một phần và thứ cần thay đổi, thêm một làn rồi vẽ lên đó. Mỗi phần có các làn cho âm lượng, cân trái phải, độ rộng, tần số cắt của bộ lọc thông thấp và thông cao, cộng hưởng, gửi reverb và gửi delay, bão hòa, giảm bit, độ sâu gate và cao độ; kênh tổng có âm lượng và một bộ lọc thông thấp.","docs.automation.p2":"Vẽ các điểm, hoặc chọn rồi di chuyển chúng; uốn đường nối giữa hai điểm; đóng dấu một hình dạng lên một vùng — dốc, đường cong chữ S, hình sin, tam giác, vuông hay răng cưa, hoặc bậc ngẫu nhiên — và sao chép, dán một vùng. Cú quét hay cú rơi riêng của một động tác có thể được chỉnh ngay trên làn mà nó phát. Tự động hóa được đọc theo từng sample, khi phát trực tiếp cũng như khi kết xuất.","docs.sections.p1":"Mở menu của một đoạn từ tiêu đề của nó, hoặc nhấn M, để đổi tên, đổi loại hay độ dài, dời nó lên trước hoặc ra sau, chèn một đoạn mới trước hoặc sau nó, gỡ hoặc khóa nó. Bạn cũng có thể kéo một đoạn để sắp xếp lại: mọi thứ trong đoạn sẽ đi theo nó.","docs.reroll.p1":"Khóa một đoạn hay một clip bạn thích, và Tạo lại sẽ rút lại phần còn lại. Nó không bao giờ động đến một đoạn đã khóa hay một clip bạn đã chỉnh, và không bao giờ xê dịch những thứ bên cạnh. Sau đó, Những gì đã thay đổi liệt kê mọi phần và động tác nó đã đổi, theo từng đoạn.","docs.reroll.p2":"Thêm động tác mở một bảng chứa mọi động tác, các động tác của chính bản phối này được xếp trước: đặt một động tác lên dải động tác, rồi kéo, kéo giãn hoặc xóa nó. Chọn một động tác để mở bảng thông tin của nó — điểm bắt đầu, độ dài, các phần và thiết lập riêng, như dải tần của bộ lọc hay số bậc của hiệu ứng lắp bắp — và Nghe thử nó trong khi bản nghe thử đang phát.","docs.history.p1":"Mỗi thay đổi trong chế độ xem phối khí bài hát là một bước trong lịch sử hoàn tác và làm lại không giới hạn. Các nút Hoàn tác và Làm lại ở trên cùng ghi tên bước đó; hoặc nhấn Ctrl/Cmd+Z và Ctrl/Cmd+Shift+Z (hoặc Ctrl+Y). Lịch sử được lưu cùng dự án DAW của bạn.","docs.history.p2":"Mỗi thay đổi cũng được ghi ngay vào máy tính của bạn, nên nếu DAW đóng trước khi bạn lưu, dự án sẽ mở lại ở thay đổi cuối cùng và báo cho bạn biết. Nếu thay đổi đó thật ra thuộc về một bản sao khác — một dự án cũ hơn được mở lại sau khi Lưu thành — hãy chọn Giữ phiên bản đã lưu.","docs.shelf.p1":"Menu Bản phối chứa mọi bản phối của vòng lặp bạn đang mở: Bản phối mới, Nhân bản, Đổi tên, Xóa, Chuyển — ở ô nhịp kế tiếp khi đang phát, ngay lập tức khi đã dừng — và So sánh, một phép A/B giữa hai bản bất kỳ. Mỗi bản phối giữ bốn ảnh chụp, từ A đến D: nhấn vào một ảnh chụp để gọi lại, hoặc Shift-nhấp để giữ bản phối hiện tại ở đó.","docs.shelf.p2":"Xuất bản phối… ghi một bản phối thành tệp .unarr, không kèm vòng lặp của nó. Nhập bản phối… đặt một bản phối lên vòng lặp bạn đang mở, tìm chỗ cho từng đoạn, clip, động tác và làn theo đúng vai trò của chúng, rồi liệt kê những gì không có chỗ.","docs.keys.intro":"Mọi thao tác chỉnh sửa trong chế độ xem phối khí bài hát đều làm được mà không cần chuột. Trong Unloop, nhấn <kbd>?</kbd> để mở bảng này; trên Mac, <kbd>Ctrl/⌘</kbd> là <kbd>⌘</kbd>.","shortcutScope.everywhere":"Mọi nơi","shortcut.undo":"Hoàn tác","shortcut.redo":"Làm lại","docs.keys.or":"hoặc","shortcut.sheet":"Hiện bảng này","shortcut.preview":"Phát hoặc tạm dừng bản nghe thử khi DAW đang dừng","shortcut.closeDialog":"Đóng hộp thoại, thẻ hoặc bảng","shortcutScope.timeline":"Chế độ xem phối khí bài hát","shortcut.nextClip":"Chọn clip tiếp theo","shortcut.previousClip":"Chọn clip trước đó","shortcut.clipAbove":"Chọn clip trên làn phía trên","shortcut.clipBelow":"Chọn clip trên làn phía dưới","shortcut.selectAll":"Chọn mọi clip","shortcut.deselect":"Bỏ chọn tất cả, hoặc hủy thao tác kéo","shortcut.moveEarlier":"Dời các clip đã chọn lên trước một bước bám lưới","shortcut.moveLater":"Dời các clip đã chọn ra sau một bước bám lưới","shortcut.moveUp":"Chuyển các clip đã chọn lên làn phía trên","shortcut.moveDown":"Chuyển các clip đã chọn xuống làn phía dưới","shortcut.endEarlier":"Rút ngắn clip từ phần cuối","shortcut.endLater":"Kéo dài clip ở phần cuối","shortcut.startEarlier":"Kéo dài clip ở phần đầu","shortcut.startLater":"Rút ngắn clip từ phần đầu","shortcut.gainUp":"Tăng mức của các clip","shortcut.gainDown":"Giảm mức của các clip","shortcut.cursorEarlier":"Dời con trỏ chỉnh sửa lên trước","shortcut.cursorLater":"Dời con trỏ chỉnh sửa ra sau","shortcut.split":"Tách tại con trỏ chỉnh sửa","shortcut.fades":"Giữ tay nắm mờ dần của clip","shortcut.reverse":"Đảo ngược các clip đã chọn","shortcut.lock":"Khóa hoặc mở khóa các clip đã chọn","shortcut.copy":"Sao chép các clip đã chọn","shortcut.cut":"Cắt các clip đã chọn","shortcut.paste":"Dán tại con trỏ chỉnh sửa","shortcut.clone":"Nhân bản phía sau vùng chọn","shortcut.duplicate":"Sao chép tại chỗ","shortcut.delete":"Xóa các clip đã chọn, hoặc động tác đã chọn","shortcut.clipMenu":"Mở menu của clip","shortcut.sectionMenu":"Mở menu của đoạn","shortcutScope.fades":"Khi đang giữ tay nắm mờ dần","shortcut.fadeLonger":"Kéo dài đoạn mờ dần thêm một bước bám lưới","shortcut.fadeShorter":"Rút ngắn đoạn mờ dần một bước bám lưới","shortcut.fadeCurveUp":"Uốn đường cong mờ dần lên trên","shortcut.fadeCurveDown":"Uốn đường cong mờ dần xuống dưới","shortcut.fadeOtherSide":"Chuyển sang đoạn mờ dần bên kia","shortcut.fadeDone":"Thả tay nắm mờ dần","shortcutScope.fader":"Trên một fader","shortcut.faderUp":"Nâng fader một bước","shortcut.faderDown":"Hạ fader một bước","shortcut.faderFineUp":"Nâng fader một bước nhỏ","shortcut.faderFineDown":"Hạ fader một bước nhỏ","shortcut.faderBigUp":"Nâng fader sáu bước","shortcut.faderBigDown":"Hạ fader sáu bước","shortcut.faderTop":"Đẩy fader lên tối đa","shortcut.faderOff":"Kéo fader xuống hết (tắt)","shortcutScope.lane":"Trên một làn tự động hóa","shortcut.pointsDelete":"Xóa các điểm đã chọn","shortcut.pointsCancel":"Hủy thao tác kéo","shortcutScope.search":"Trong ô tìm kiếm","shortcut.searchNext":"Kết quả tiếp theo","shortcut.searchPrevious":"Kết quả trước đó","shortcut.searchPick":"Chọn kết quả","shortcut.searchClose":"Đóng kết quả","shortcutScope.menu":"Trong một menu","shortcut.menuNext":"Mục tiếp theo","shortcut.menuPrevious":"Mục trước đó","shortcut.menuClose":"Đóng menu","docs.privacy.p1":"Unloop không có tài khoản và không đo lường từ xa, và plugin cùng ứng dụng độc lập hoàn toàn không chứa mã mạng. Vòng lặp, dự án và bản nhạc của bạn không bao giờ rời khỏi máy tính, và một vòng lặp, một dự án hay một thư mục xuất nằm trên ổ đĩa mạng sẽ bị từ chối trước khi bất cứ thứ gì trên đó bị động tới.","docs.privacy.p2":"Nó giữ các tệp riêng trong thư mục dữ liệu ứng dụng của bạn (%APPDATA%\\Freally Unloop trên Windows): câu trả lời về giấy phép, tùy chọn của bạn, Dự án gần đây, chỉ mục của Thư viện vòng lặp, bộ nhớ đệm bản thu (tối đa 2 GB) và các tệp mà các phiên bản plugin dùng để gặp nhau. Nó không bao giờ ghi vào các thư mục vòng lặp của bạn; các tệp xuất và dự án được lưu ở nơi bạn chọn.","docs.privacy.p3":"Nó không chứa bất kỳ loại AI nào: mọi bản phối đều được lên kế hoạch bằng các quy tắc tất định dựa trên dữ liệu phối khí đã được nghiên cứu và được trình diễn bằng xử lý tín hiệu cổ điển, và một cổng kiểm tra khi dựng sẽ thất bại nếu có thư viện học máy nào được thêm vào.","docs.limits.midi":"MIDI — mẫu bài hát, vòng lặp MIDI và Bác sĩ velocity — sẽ có trong phiên bản 0.7.0. Trước đó, giọng của vòng lặp chưa được xác định, nên tên tệp mặc định không ghi giọng.","docs.limits.picture":"Khi kéo, Unloop chưa hiển thị hình ảnh của thứ bạn đang kéo.","docs.limits.throw":"Một cú ném vang hay ném trễ ở ô nhịp cuối bị cắt tại vạch ô nhịp cuối cùng của bản nhạc; bản kết xuất không ngân tiếp quá điểm đó.","docs.limits.display":"Trên màn hình thứ hai có tỷ lệ hiển thị khác, trình chỉnh sửa lấy kích thước theo màn hình chính.","docs.limits.hands":"Unloop chưa được thử thủ công trong mọi DAW, trên mọi hệ điều hành. Đó là việc của bản ứng viên phát hành, trước 1.0.0.","kit.skip":"Chuyển đến nội dung","kit.nav.site":"Trang web","kit.nav.home":"Trang chủ","kit.nav.features":"Tính năng","kit.nav.documentation":"Tài liệu","kit.nav.changelog":"Nhật ký thay đổi","kit.nav.language":"Ngôn ngữ","kit.nav.allApps":"Tất cả ứng dụng Freally","kit.badge.progress":"v0.6.0 đã xong · tiếp theo là v0.6.5","kit.cta.features":"Xem mọi tính năng","kit.cta.docs":"Đọc tài liệu","kit.price":"Freally Unloop hiện miễn phí, nhưng có thể không miễn phí mãi mãi: các phiên bản sau này có thể được bán.","kit.noDownloads":"Hiện chưa có bản tải xuống, và mã nguồn là riêng tư.","kit.label.overview":"Tổng quan","kit.label.inside":"Bên trong","kit.label.roadmap":"Lộ trình","kit.ladder.done":"Xong","kit.ladder.planned":"Đã lên kế hoạch","kit.ladder.goal":"Mục tiêu","kit.ladder.later":"Về sau","kit.label.honesty":"Trung thực","kit.family.label":"Gia đình Freally","kit.family.title":"<span class=\"hl-muted\">Một gia đình.</span> <span class=\"hl-bright\">Tám ứng dụng.</span>","kit.cta.label":"Những gì đã thay đổi","kit.cta.title":"<span class=\"hl-muted\">Mỗi phiên bản,</span> <span class=\"hl-bright\">đều được ghi lại.</span>","kit.cta.lede":"Nhật ký thay đổi liệt kê mọi thứ đã thay đổi trong Freally Unloop, theo từng phiên bản, bằng cả mười tám ngôn ngữ.","kit.cta.changelog":"Đọc nhật ký thay đổi","kit.footer.thisApp":"Ứng dụng này","kit.footer.family":"Gia đình Freally","kit.footer.home":"Freally Products","kit.status.devVersion":"Đang phát triển · v0.6.0","kit.head.features":"<span class=\"hl-muted\">Mọi thứ nó làm được,</span> <span class=\"hl-bright\">đặt cạnh nhau.</span>","kit.label.numbers":"Qua các con số","kit.numbers.lead":"Mỗi con số đều được đếm từ chính ứng dụng. Không có gì là ước tính, và không có gì được làm tròn lên.","kit.label.free":"Miễn phí hôm nay","kit.label.compare":"So sánh","kit.label.principles":"Nguyên tắc","kit.label.limits":"Giới hạn","kit.states.title":"Ý nghĩa của các trạng thái","kit.states.done":"đã dựng và gắn thẻ, nhưng không phải bản tải xuống trên trang này","kit.states.planned":"vẫn chưa được xây dựng","kit.states.goal":"phiên bản mà con đường này hướng tới","kit.states.later":"sau đó, và chưa được lên lịch","kit.states.ladder":"Xem mọi nấc trên con đường","kit.head.documentation":"<span class=\"hl-muted\">Cách hoạt động,</span> <span class=\"hl-bright\">từng bước một.</span>","kit.search.placeholder":"Tìm kiếm trong tài liệu","kit.docs.contents":"Mục lục","kit.head.changelog":"<span class=\"hl-muted\">Mọi thay đổi,</span> <span class=\"hl-bright\">theo từng phiên bản.</span>","kit.changelog.lede":"Mới nhất trước: mọi thứ đã thay đổi trong Freally Unloop, bằng mọi ngôn ngữ của trang này.","kit.changelog.versions":"Phiên bản","kit.search.none":"Không có gì trên trang này khớp với điều đó.","changelog.c4b898d0a012":"<span class=\"release__meta\"><span class=\"release__ver\">v0.6.0</span><time class=\"release__date\" datetime=\"2026-10-01\">2026-10-01</time></span><span class=\"release__title\">T: Dòng thời gian</span>","changelog.0a8e4d670c30":"Bản phối là của bạn để chỉnh sửa, đến từng chi tiết, và mọi đầu ra đều phát đúng những gì bạn đã chỉnh. Di chuyển, sao chép, dán, nhân bản, đổi độ dài, trượt nội dung và tách clip; vẽ đoạn mờ dần với ba tay nắm của MIDI Master; điều khiển fader của clip, của phần và fader tổng; vẽ tự động hóa; định hình lại các đoạn; khóa những gì bạn thích và tạo lại phần còn lại; tự tay đặt động tác — mỗi thay đổi là một bước hoàn tác, hoàn tác và làm lại bao xa tùy ý. Dự án của một vòng lặp giờ chứa một kệ bản phối mà bạn chuyển qua lại ở ô nhịp kế tiếp, và một bản phối có thể đi riêng dưới dạng tệp <code>.unarr</code>.","changelog.6b02e0d363a4":"Đã thêm","changelog.b5f9159dff5a":"<strong>Dòng thời gian.</strong> Mọi clip trên bản đồ đều chỉnh sửa được: chọn (nhấp chuột, <code>Shift</code>, khung chọn, <code>Ctrl/Cmd+A</code>), di chuyển (theo lưới; <code>Alt</code> để bỏ qua lưới; chỉ đổi làn giữa những phần có thể dùng chung một làn), xóa, nhân bản phía sau vùng chọn (<code>Ctrl/Cmd+D</code>), sao chép tại chỗ (<code>Shift+D</code>), sao chép, cắt và dán tại con trỏ chỉnh sửa (khi dán vào làn không tương thích, clip được đề xuất những làn nó có thể đặt lên, không bao giờ bị âm thầm thay đổi), đổi độ dài từ cả hai cạnh (vòng lặp lặp lại khi vượt quá độ dài của nó), trượt nội dung (kéo với <code>Alt</code>), tách (<code>S</code>), đảo ngược, đổi tên, đổi màu và <em>Về lại kế hoạch</em> — cả từ menu ngữ cảnh. Một clip đã di chuyển, đã trượt hoặc đã đảo ngược được phát từ đúng vị trí của nó trong vòng lặp đã thu.","changelog.91d85c02a166":"<strong>Mờ dần y hệt chế độ phối khí bài hát của MIDI Master</strong>: ba tay nắm mỗi bên — độ dài ở cạnh trên của clip, độ cong trên đường mờ dần — không bao giờ chồng chéo nhau, dù clip dài bao nhiêu; clip ngắn nhất dài một nốt móc bốn (1/64).","changelog.c0ccdbacbd8c":"<strong>Fader.</strong> Một tay nắm mức ngay trên clip (−∞ đến +6 dB, <code>Shift</code> để chỉnh tinh, nhấp đúp để về 0 dB), các fader phần trên bàn trộn và một fader tổng — cùng một luật fader — mọi thay đổi đều nghe được trong khi kéo và thành một bước hoàn tác khi kết thúc.","changelog.2bcc3000b0a9":"<strong>Làn tự động hóa</strong> cho âm lượng, cân trái phải, độ rộng, tần số cắt lọc thông thấp và thông cao, cộng hưởng, gửi reverb và delay, bão hòa, giảm bit, độ sâu gate và cao độ trên mọi phần, cùng âm lượng tổng và lọc thông thấp tổng — vẽ, uốn, chọn và di chuyển; đóng dấu hình dạng (dốc, đường cong chữ S, hình sin, tam giác, vuông, răng cưa, bậc ngẫu nhiên) và sao chép/dán một vùng; cú quét hay cú rơi riêng của một động tác được chỉnh trên làn mà nó phát. Đọc theo từng sample, khi phát trực tiếp cũng như khi Kết xuất.","changelog.7d436c4c3696":"<strong>Các đoạn.</strong> Chèn, xóa, kéo để sắp xếp lại (mọi thứ trong đoạn đi theo nó), đổi độ dài, đổi loại (hoạt động của đoạn được rút lại cho loại mới), đổi tên và khóa — từ menu của đoạn hoặc từ tiêu đề của nó.","changelog.48c0b2ee5ed9":"<strong>Khóa và tạo lại.</strong> Một lần tạo lại không bao giờ động đến đoạn đã khóa hay clip đã chỉnh, và không bao giờ xê dịch những thứ bên cạnh; <em>Những gì đã thay đổi</em> liệt kê mọi phần và động tác nó đã đổi, theo từng đoạn.","changelog.e101a7e88895":"<strong>Tự tay đặt động tác.</strong> Một bảng chứa mọi động tác (các động tác riêng của mô hình được xếp trước), được đặt, kéo, kéo giãn và xóa trên dải đánh dấu; bảng thông tin động tác chỉnh các thông số và các phần của nó, và cho nghe thử nó trong khi đang nghe thử bản nhạc — được dựng y hệt cách bộ lập kế hoạch dựng một động tác.","changelog.48cc96242f52":"<strong>Hoàn tác và làm lại không giới hạn</strong> cho mọi thay đổi trong chế độ xem phối khí bài hát, do phiên bản plugin nắm giữ và lưu cùng dự án, từ các nút Hoàn tác và Làm lại trên thanh trên cùng (mỗi nút ghi tên bước của nó) hoặc <code>Ctrl/Cmd+Z</code>, <code>Ctrl/Cmd+Shift+Z</code>, <code>Ctrl+Y</code>. <strong>An toàn khi gặp sự cố:</strong> mọi thay đổi được ghi ngay vào thư mục dữ liệu ứng dụng của bạn (ngoài luồng riêng của host), và một host đã đóng trước khi lưu sẽ mở lại ở thay đổi cuối cùng của bạn, và báo rõ điều đó — kèm <em>Giữ phiên bản đã lưu</em> cho trường hợp thay đổi đó thuộc về một bản sao khác (một dự án cũ hơn được mở lại sau khi <em>Lưu thành</em>). Một track được nhân bản giữ bản tự động lưu của riêng nó.","changelog.4a2ef5527abc":"<strong>Khi host thay đổi vòng lặp, bản phối được khớp lại.</strong> Một độ dài vòng lặp hay số chỉ nhịp mới sẽ đặt các chỉnh sửa của bạn lên đó như khi nhập bản phối, thay vì bỏ chúng đi; lịch sử hoàn tác bắt đầu lại từ đó.","changelog.7e8282605542":"<strong>Lưới và độ sạch.</strong> Bám lưới theo ô nhịp, phách, 1/8, 1/16, các liên ba của chúng, hoặc tắt; thu phóng với bản đồ thu nhỏ; tô bóng theo câu nhạc 4/8/16 ô nhịp; crossfade tự động 3 ms ở chỗ các clip gặp nhau; và khi tắt bám lưới, cạnh clip được dịch về điểm giao cắt không gần nhất của vòng lặp (trong phạm vi 1 ms). Không chuỗi chỉnh sửa nào gây tiếng click.","changelog.9ed31073c953":"<strong>Kệ bản phối.</strong> Một vòng lặp, nhiều bản phối có tên, từ menu Bản phối trên thanh trên cùng: <em>Bản phối mới</em>, <em>Nhân bản</em>, <em>Đổi tên</em>, <em>Xóa</em> (hoàn tác được), <em>Chuyển</em> — ở vạch ô nhịp kế tiếp khi đang phát, ngay lập tức khi đã dừng — và <em>So sánh</em>, một công tắc A/B giữa hai bản bất kỳ; mỗi bản phối có bốn ảnh chụp (A–D). Việc chuyển không bao giờ thu lại hay giải mã lại vòng lặp, và một bản phối được chuyển đi rồi quay lại vẫn y nguyên như trước. Mỗi thao tác trên kệ là một bước hoàn tác, và tệp <code>.unloop</code> mang theo toàn bộ kệ.","changelog.04b5ecf4f4ca":"<strong>Tệp bản phối <code>.unarr</code>.</strong> <em>Xuất bản phối…</em> ghi một bản phối mà không kèm vòng lặp của nó; <em>Nhập bản phối…</em> đặt nó lên vòng lặp bạn đang mở — các đoạn, clip, động tác và làn được tìm chỗ theo đúng vai trò của chúng (điệp khúc thứ hai, phần trống của phiên khúc), các đoạn được đặt theo số vòng lặp trọn vẹn, co giãn theo độ dài của vòng lặp mới — và liệt kê những gì không có chỗ.","changelog.900ccf7596b0":"<strong>Bàn phím là trên hết.</strong> Một bảng phím tắt duy nhất vừa điều khiển ứng dụng vừa tạo ra bảng tra cứu — nhấn <code>?</code> trong Unloop, hoặc xem trang tài liệu. Mọi chỉnh sửa trên dòng thời gian đều làm được không cần chuột: chuyển qua các clip, di chuyển chúng theo bước bám lưới, đổi độ dài, đổi mức, giữ tay nắm mờ dần, tách, đảo ngược, khóa và mở menu của chúng. Phím của dòng thời gian chỉ có tác dụng khi bản đồ (hoặc không gì cả) đang có tiêu điểm, không bao giờ tác động lên một nút, một làn hay một hộp thoại đang có tiêu điểm. Bản đồ được đặt tên và mô tả cho trình đọc màn hình, đến từng clip và từng tay nắm.","changelog.2a6141e43be0":"Đã thay đổi","changelog.7757cf2e3226":"<strong>Trạng thái dự án dùng lược đồ 6, và tài liệu <code>.unloop</code> dùng lược đồ 2</strong>: các chỉnh sửa, lịch sử, kệ bản phối, cùng các chỉnh sửa và ảnh chụp của từng bản phối. Dự án và tệp cũ hơn vẫn mở được như trước.","changelog.852a0be917e2":"<strong>Các crate dùng chung của Freally chuyển lên <code>shared-v5</code></strong> — từ <code>shared-v3</code> của MIDI Master lên <code>shared-v5</code>, và bản fork nih-plug của nó ở <code>df472391</code>: trang của trình chỉnh sửa nằm đúng dưới cửa sổ khi cửa sổ bị di chuyển (WebView2 được báo rằng cửa sổ đã di chuyển và được đặt lại bên dưới nó), <code>freally-extract</code> và <code>process_mode()</code> của nih-plug đã dùng được, và ảnh chụp danh sách tên được lấy lại ở tag mới (dữ liệu không đổi).","changelog.fb1d01817381":"<strong>Kho mã nguồn được công khai</strong> — <code>MikesRuthless12/freally-unloop</code>, Bảo lưu mọi quyền; các crate dùng chung đến từ kho công khai <code>MikesRuthless12/freally-midi-master</code>, và bản dựng phát hành cho macOS không cần khóa bí mật nào.","changelog.01c79b299c9b":"<strong>Tích hợp liên tục chạy trên GitHub</strong>, trên Windows, Linux và macOS, cho mỗi lần push và pull request — mọi cổng kiểm tra, clap-validator và pluginval ở độ nghiêm ngặt 10 trên mọi máy chạy (AU trên macOS). Không commit nào còn mang <code>[skip ci]</code> nữa.","changelog.8c8f3f1edad1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.5.0</span><time class=\"release__date\" datetime=\"2026-09-28\">2026-09-28</time></span><span class=\"release__title\">C: Thu, nghe thử và kết xuất</span>","changelog.3ccc718cc694":"MVP đã hoàn tất. Mỗi phiên bản plugin thu một chu kỳ của vòng lặp và phát bản nhạc từ bộ nhớ; toàn bộ bản phối có thể nghe thử ngay trong Unloop khi DAW đang dừng; <strong>Kết xuất</strong> dựng nó ra — bản mix, stem, một phần hay một đoạn — dưới dạng WAV, AIFF, FLAC hoặc MP3, đúng từng sample những gì bạn đã nghe trực tiếp; khay kéo thả nó thẳng vào các track của bạn; mỗi tệp đều có một biên nhận đi kèm; và một vòng lặp được lưu thành dự án <code>.unloop</code> mà bạn có thể mở lại, hoặc tìm lại trong Thư viện vòng lặp cùng các vòng lặp khác của bạn.","changelog.b88c7903914f":"<strong>Thu.</strong> Sau khi nhấn <em>Tạo</em>, mỗi phiên bản plugin ghi đúng một chu kỳ của vòng lặp — <code>loop_bars</code> nhạc tính từ ranh giới vòng lặp kế tiếp, chính xác đến từng sample ở 44,1, 48 và 96 kHz — trực tiếp từ đầu vào của DAW, không bao giờ từ đầu ra của chính Unloop. Nhãn <strong>TRỰC TIẾP / ĐÃ THU</strong> cạnh các nút nghe thử cho biết trạng thái hiện tại (đang chờ, đang thu, đã thu, đã cũ) kèm <em>Thu lại</em> và <em>Quên bản thu</em>. Nếu dừng, tua hoặc đổi nhịp độ giữa chừng, phần đã thu dở sẽ bị bỏ và việc thu được thử lại ở lần phát tiếp theo; một vòng lặp dài hơn 64 giây sẽ bị từ chối kèm lời giải thích. Các bản thu được lưu theo nội dung (BLAKE3) trong thư mục dữ liệu ứng dụng của bạn, tối đa 2 GB, bản lâu chưa dùng nhất bị xóa trước; dự án của host chỉ lưu mã băm, và một dự án có bản thu đã mất sẽ yêu cầu bạn phát vòng lặp một lần.","changelog.b3429b1f4985":"<strong>Vòng lặp đã đổi — thu lại?</strong> Khi vòng lặp đang đi vào không phải là vòng lặp đã thu trong hai chu kỳ liên tiếp (so sánh từng dải tần), nhãn sẽ báo điều đó. Không có gì bị thay thế khi nó đang phát; thu lại hay không là do bạn nhấn.","changelog.09d9a80b48ef":"<strong>Phát từ bộ nhớ.</strong> Sau khi thu, một phiên bản plugin phát bản nhạc từ bản thu của nó, khóa theo vị trí của host — không bị trôi trên một vòng lặp có chu kỳ không phải là số nguyên sample, có crossfade khi nguồn thay đổi, và vẫn không thêm chút độ trễ nào. Các động tác dùng bộ nhớ đọc từ bản thu; trước khi có bản thu, chúng đọc quá khứ gần của vòng lặp, và bản đồ ghi rõ điều đó.","changelog.2d3fbd1189a2":"<strong>Nghe thử ngay trong Unloop.</strong> Khi host đang dừng, các nút phát, tạm dừng, dừng và lặp trong phần master (hoặc phím cách) phát cả bản nhạc trong Unloop — mọi phiên bản plugin trên kênh cùng phát, mỗi phiên bản từ bản thu của mình, khớp đến cùng một sample trong một DAW và trong phạm vi một khối khi chạy giữa các tiến trình. Nhấn vào thước của bản đồ để nhảy tới; lặp một đoạn. Nhấn phát trong host và host tiếp quản ngay lập tức — bản nghe thử tạm dừng tại chỗ âm thanh đang phát và báo rõ điều đó. Những phần mà host không chạy khi đang dừng (các track không ở chế độ live của Logic) và những phần chưa thu được gì đều được nêu tên.","changelog.5f7f65713c74":"<strong>Động tác II</strong>: đảo ngược, nửa nhịp (băng và kéo giãn), cổng nhịp, lo-fi, ném vang (bộ vang riêng của Unloop), ném trễ (móc đơn chấm dôi, ping-pong), rơi cao độ và tua lại — mỗi động tác có bài kiểm thử riêng về thời điểm, tiếng click và CPU. Các đoạn nửa nhịp giờ đã được trình diễn (từ bản thu, ở tốc độ đầy đủ cho đến khi có bản thu). Bốn động tác cùng lúc — dù có động tác mới nào trong đó — tốn của toàn bộ lõi âm thanh ≈25–27 µs trên một khối 128 sample ở 48 kHz: khoảng 1 % của một nhân CPU, nằm trong ngân sách 1,5 %.","changelog.aae38e7e09b4":"<strong>Kết xuất.</strong> Bản nhạc được dựng ngoại tuyến từ các bản thu qua chính đoạn mã phát nó trực tiếp — mỗi phần một stem, trước fader và đủ độ dài từ ô nhịp 1 để DAW nào cũng xếp chúng thẳng hàng, và bản mix là tổng của chúng. Phát trực tiếp và bản kết xuất được kiểm thử để luôn bằng nhau với mọi động tác mới và clip nửa nhịp — khớp từng bit trong các khối của chính bản kết xuất, và các động tác dùng bộ nhớ chênh lệch dưới −100 dB ở các kích thước khối khác mà host dùng; kết xuất hai lần cho ra cùng các byte. Một bản kết xuất dài ba phút với tám stem mất khoảng 3 giây, có thanh tiến trình cho mỗi tệp và nút <strong>Hủy</strong>, không để lại gì.","changelog.30dab5974741":"<strong>WAV, AIFF, FLAC và MP3.</strong> WAV 16/24 bit hoặc 32 bit dấu phẩy động với khối <code>acid</code> ở mọi độ sâu bit, để Ableton, FL và Acid co giãn nó theo nhịp độ của bạn; AIFF 16/24 (định dạng này không có chỗ ghi nhịp độ, và hộp thoại nói rõ điều đó); FLAC 16/24 với thẻ <code>BPM</code>; MP3 128–320 kbps với thẻ <code>TBPM</code> (kèm ghi chú rằng MP3 thêm độ trễ bộ mã hóa — hãy dùng WAV hoặc FLAC cho stem cần khớp nhau). Tần số lấy mẫu như khi thu hoặc 44,1/48/88,2/96 kHz (MP3 tối đa 48), được chuyển đổi trước khi phần đầu tệp ghi tần số đó; dither TPDF có hạt giống khi giảm độ sâu bit, giống hệt nhau ở mọi lần kết xuất. Trong các bài kiểm thử, mọi định dạng đều được đọc lại bằng bộ giải mã riêng của Unloop.","changelog.3cff712e7690":"<strong>Đồng hồ kết xuất và bộ giới hạn an toàn.</strong> Mức đỉnh (dBFS), đỉnh thực lấy mẫu vượt 4× (dBTP) và độ to tích hợp (LUFS, ITU-R BS.1770-4) của bản mix, hiển thị khi xuất xong; một bộ giới hạn −1 dBTP tùy chọn chỉ áp dụng cho bản mix, cho biết nó đã kéo bản mix xuống bao nhiêu.","changelog.f311d0c466d8":"<strong>Hộp thoại xuất</strong> (<strong>KẾT XUẤT</strong> trong phần master): nội dung — bản mix, các stem, bất kỳ phần nào, một đoạn hay cả bản nhạc — định dạng, chất lượng, tần số, dither, bộ giới hạn và biên nhận, cùng các tên tệp sẽ được ghi, được liệt kê trực tiếp từ mẫu của bạn bởi chính đoạn mã đặt tên tệp. Mẫu mặc định là <code>{genre} - {mode} - {what} - {bpm} BPM - {key}</code>; có sẵn <code>{model}</code> nếu bạn muốn đưa cái tên vào. <strong>Không tên tệp mặc định nào chứa tên nghệ sĩ hay nhà sản xuất</strong> — một bài kiểm thử duyệt qua mọi cái tên trong danh sách, mọi chế độ và mọi kiểu xuất để bảo đảm điều đó.","changelog.361d5bae41fd":"<strong>Khay kéo.</strong> Kéo bản mix, các stem, một phần hoặc một đoạn vào các track của bạn (mặc định là WAV 24 bit); các tệp được kết xuất trước khi bắt đầu kéo, nên khi thả xuống tệp đã trọn vẹn.","changelog.8552eba608bc":"<strong>Biên nhận, bật theo mặc định.</strong> <code>&lt;name&gt;.unloop-receipt.json</code> đi kèm mỗi lần xuất và mỗi lần kéo: phiên bản của Unloop và của bộ dữ liệu, tag của Freally MIDI Master, mô hình, chế độ và hạt giống, mã băm kế hoạch, mã băm bản thu của từng phần, các tệp và những gì đã được yêu cầu — đủ để tạo lại đúng bản nhạc đó. Tắt chúng là một tùy chọn, không bao giờ là mặc định.","changelog.385eadae4891":"<strong>Dự án vòng lặp (<code>.unloop</code>).</strong> <em>Lưu dự án vòng lặp…</em> và <em>Mở dự án vòng lặp…</em> từ nút thư mục ở đầu thanh trên cùng: vòng lặp được lưu một lần (các phần của nó dưới dạng FLAC 24 bit) cùng bản phối trên nó. Lưu cùng một dự án hai lần cho ra cùng các byte; mở nó cho ra cùng kế hoạch, khớp đến mã băm, và cùng bản thu mà không cần phát qua một lượt. Một dự án từ phiên bản Unloop mới hơn bị từ chối toàn bộ (&quot;Được tạo bằng Unloop mới hơn — hãy cập nhật để mở&quot;); nếu một phần bị thiếu hoặc hỏng, phần còn lại vẫn mở và phần cần cấp lại được nêu tên. Việc lưu không bao giờ ghi đè lên tệp — tên đã có sẽ được thêm <code> (2)</code> — và khi lưu lại một dự án, mọi thứ trong đó mà phiên bản plugin này không tạo ra đều được giữ nguyên.","changelog.a86b818719c2":"<strong>Thư viện vòng lặp.</strong> Thêm các thư mục vòng lặp của bạn: mọi tệp <code>.unloop</code> và mọi tệp WAV, AIFF, FLAC, MP3 và MIDI trong đó được liệt kê kèm số ô nhịp, BPM (<em>từ tệp</em> — từ khối <code>acid</code>, thẻ hoặc tên tệp — cho đến khi tính năng nhận diện có ở <code>v0.7.0</code>), thẻ, số lần đã phối, lần sửa cuối và một dạng sóng thu nhỏ. Tìm kiếm và lọc theo BPM, giọng, thẻ hoặc <em>chưa từng phối khí</em>; nhấn vào một dòng để nghe (<code>↑/↓</code> để duyệt, <code>Esc</code> để dừng) — chỉ trong Unloop, không bao giờ điều khiển bộ phát của DAW — và <strong>Phối khí</strong> nó khi nó đúng là một vòng lặp. Hai nghìn tệp được lập chỉ mục trong một hai giây, ngoài luồng của host. Nó chỉ đọc các thư mục của bạn, không bao giờ làm gì khác. Vòng lặp MIDI đã được liệt kê từ bây giờ và sẽ phối được ở <code>v0.7.0</code>.","changelog.a26b2595dfc9":"<strong>Dự án gần đây</strong>, mới nhất ở trên cùng, một cú nhấp để mở lại; một dự án đã bị di chuyển hiện là bị thiếu, kèm <em>Xóa khỏi danh sách</em> (chỉ gỡ dòng, không bao giờ xóa tệp).","changelog.2e4a3278fa31":"<strong>Bộ cắt vòng lặp</strong> — <em>Tạo vòng lặp từ tệp dài hơn…</em>: chọn ô nhịp bắt đầu và độ dài (1, 2, 4, 8 hoặc 16 ô nhịp) ở một nhịp độ, nghe đoạn cắt lặp đi lặp lại, rồi <em>Phối khí</em> nó thành một dự án vòng lặp mới. Đoạn cắt chính xác đến từng sample, và tệp nguồn không bao giờ bị thay đổi.","changelog.22f2979096ba":"<strong>Bảng liên kết</strong> cho biết phiên bản plugin nào đã có bản thu, và phiên bản nào không được host chạy trong khi bản nghe thử đang phát.","changelog.d0c12bfcdf93":"<strong>Mọi mã băm kế hoạch đều đổi — còn các kế hoạch thì không.</strong> Một kế hoạch ghi tên tag Freally MIDI Master mà dữ liệu của nó được nhập từ đó (<code>mm-shared-v2/…</code>, trước là <code>mm-shared-v1/…</code>); dữ liệu không đổi, nên mọi cái tên, chế độ và hạt giống vẫn phối y hệt như trước. 24 kế hoạch chuẩn chỉ thay đổi ở dòng tiêu đề.","changelog.81dd6b6d682d":"<strong>Các crate dùng chung của Freally chuyển lên <code>shared-v2</code></strong> — <code>freally-encode</code> của MIDI Master (mọi byte của mọi tệp được xuất) và <code>freally-drag</code> (kéo thả gốc trên Windows, macOS và Linux), được tách ra khỏi MIDI Master cho Unloop, nằm cạnh engine và bộ chuyển đổi webview ở cùng tag. Engine giờ tự dựng được, nên cách khắc phục tạm thời phải checkout toàn bộ trong CI Linux đã được bỏ.","changelog.25e088b374a9":"<strong>Một bộ trình diễn cho mọi đầu ra.</strong> Lịch trình và bộ trình diễn được chuyển vào một crate riêng, <code>performance</code>, mà phát trực tiếp, bản nghe thử và Kết xuất đều đi qua; <code>render</code> chứa phần Kết xuất, cổng vào của các bộ mã hóa, bộ giải mã, đồng hồ đo, bộ giới hạn và vùng chứa <code>.unloop</code>.","changelog.759e88328427":"<strong>Bố cục tệp liên kết lên phiên bản 2</strong> (<code>&lt;letter&gt;.v2.mmap</code>), mang mã băm bản thu của từng phiên bản plugin và đồng hồ nghe thử của kênh. Unloop <code>v0.4.0</code> và bản này không bao giờ dùng chung một kênh giữa các tiến trình — hãy cập nhật mọi bản cùng lúc. Dự án host được lưu bằng <code>v0.4.0</code> vẫn mở được ở đây (trạng thái của nó chuyển lên lược đồ 4, tham chiếu đến bản thu); dự án được lưu ở đây sẽ bị <code>v0.4.0</code> từ chối toàn bộ.","changelog.2d5e534dd29f":"<strong>Thay đổi mức âm chuyển mượt trong 2 ms</strong> (trước là 5 ms), nên cạnh của một cổng nhịp nhanh giữ được hình dạng; mọi cạnh vẫn vượt qua bài kiểm tra tiếng click ở −60 dB.","changelog.ddd7a1094504":"<strong>Tìm kiếm quy đổi các chữ như Ø, ß và Ł</strong>, nên &quot;mo&quot; sẽ tìm ra MØ.","changelog.f6ed90cd965e":"<strong>Phần master của bàn trộn</strong> có thêm các nút nghe thử, nhãn nguồn, <strong>KẾT XUẤT</strong> và khay kéo; bộ đếm băng hiển thị <em>Đang nghe thử</em> khi bản nghe thử đang phát; thanh trên cùng bắt đầu bằng nút thư mục của dự án vòng lặp.","changelog.044bd3e3ee09":"<code>THIRD-PARTY-NOTICES.md</code> giờ liệt kê 437 thành phần (trước là 381), trong đó có bộ giải mã (Symphonia, MPL-2.0 — một bộ giải mã, điều mà chính sách giấy phép cho phép), các bộ mã hóa FLAC và MP3, bộ chuyển đổi tần số lấy mẫu và các hộp thoại tệp gốc của hệ điều hành.","changelog.1246fc93bca0":"Đã sửa","changelog.cbcb91b5782e":"<strong>Trình chỉnh sửa của Unloop dùng hồ sơ trình duyệt riêng</strong> (<code>%APPDATA%\\Freally Unloop\\webview</code>, cùng các thư mục tương ứng trên macOS và Linux), không còn dùng thư mục của Freally MIDI Master: khi hai ứng dụng chạy cạnh nhau, một trình chỉnh sửa có thể bị trống (&quot;The requested resource is in use&quot; — tài nguyên được yêu cầu đang được sử dụng).","changelog.8f6fb4eb7f42":"Bảo mật","changelog.250423c9e9f8":"Từ đợt rà soát mã và bảo mật của giai đoạn này:","changelog.075cc32b4202":"<strong>Mọi tệp đều được đọc như thể có ác ý</strong> — một tệp <code>.unloop</code>, một vòng lặp trong thư viện, một bản thu trong bộ nhớ đệm, một tùy chọn: kích thước bị giới hạn trước khi đọc, mọi độ dài được đối chiếu với số byte thực có trước khi cấp phát bất cứ thứ gì từ đó, và bị từ chối thay vì đoán mò. Bộ giải mã và bộ đọc dự án không bao giờ panic vì một tệp (các bài kiểm thử byte ngẫu nhiên và độ dài khai sai buộc chúng tuân thủ điều đó), và các phần của một dự án được giải mã lần lượt từng phần, chỉ khi phần đó được dùng, nên một tệp ác ý nhỏ không thể khiến host phải giữ hàng gigabyte.","changelog.e574701848b3":"<strong>Không gì chạm đến mạng.</strong> Một thư mục chia sẻ mạng (<code>\\\\server\\share</code>) hay một đường dẫn thiết bị bị từ chối trước khi bất cứ thứ gì chạm đến nó; một dự án, một vòng lặp, một thư mục vòng lặp hay một thư mục xuất trên ổ đĩa mạng được ánh xạ bị từ chối trước khi bất kỳ tệp nào trên đó được mở hay thậm chí được xem tới (xem tới cũng là một lần kết nối); và một thư mục xuất trỏ tới một thư mục chia sẻ — qua một liên kết hay một junction — bị từ chối trước khi bất cứ thứ gì được ghi.","changelog.24ed701d1a3d":"<strong>Không gì bị ghi đè và không gì bị ghi dở dang.</strong> Một tên tệp đã có sẽ được thêm <code> (2)</code>; các tệp được ghi ra bên cạnh rồi mới chuyển vào đúng chỗ, và một lần xuất thất bại hoặc bị hủy sẽ thu hồi những gì nó đã ghi. Tên tệp là tên đơn giản trên mọi hệ điều hành (không có tên thiết bị, không có dấu phân cách).","changelog.d189c3bc173c":"<strong>Một host gỡ Unloop ra trong khi một luồng của nó vẫn đang chạy</strong> — một hộp thoại tệp đang mở, một lần xuất đang ở bước chọn thư mục — không còn bị sập trên Windows: mỗi luồng như vậy giữ plugin lại cho đến lệnh cuối cùng của nó.","changelog.a3c71b90162b":"Hạn chế đã biết","changelog.c8a83adf7aa9":"Các bước kiểm tra host của <code>v0.5.0</code> — thu, nghe thử, kết xuất, định dạng và kéo ra ngoài trong FL Studio, Ableton Live và Reaper — đã được viết ra (<code>Live-To-Do.md</code> § 4) nhưng chưa được thử thủ công; tính năng kéo ra ngoài trên macOS và Linux đã được viết nhưng chưa được thả vào một DAW thật.","changelog.fff6674de28f":"Khi kéo, Unloop chưa hiển thị hình ảnh của thứ bạn đang kéo.","changelog.342624d6fcd1":"Một cú ném vang hay ném trễ ở ô nhịp cuối bị cắt tại vạch ô nhịp cuối cùng của bản nhạc; bản kết xuất không ngân tiếp quá điểm đó.","changelog.b11de52e56ae":"Fader của các phần ở mức 0 dB trong bản mix cho đến khi có fader trên bàn trộn (<code>v0.6.0</code>); một dự án vòng lặp chỉ chứa một bản phối cho đến khi có kệ bản phối.","changelog.7b2349c31bb6":"Giọng của vòng lặp chưa được xác định cho đến khi có tính năng nhận diện (<code>v0.7.0</code>), nên tên tệp mặc định bỏ <code>{key}</code> ra cho đến lúc đó.","changelog.2abf238bf14a":"Trên màn hình thứ hai có tỷ lệ hiển thị khác, trình chỉnh sửa lấy kích thước theo màn hình chính.","changelog.f56d1c79ff84":"Trên macOS, chưa có gì giữ plugin lại trong khi một hộp thoại hay một lần xuất đang chạy (<code>SECURITY.md</code>, mục <em>Hạn chế đã biết</em>).","changelog.13da7fa23214":"<code>v0.5.0</code> chỉ phát hành cho Windows và Linux; không có bản dựng macOS nào (AU, CLAP, VST3 hay ứng dụng độc lập) cho phiên bản này.","changelog.adb870b6c393":"<span class=\"release__meta\"><span class=\"release__ver\">v0.4.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">R: Vai trò và nhạc trưởng</span>","changelog.277edf17b8c6":"Đặt Unloop trên track của từng phần và chúng cùng trình diễn một bản nhạc. Phiên bản đầu tiên làm nhạc trưởng; mọi phiên bản khác theo kế hoạch của nó chính xác đến từng sample và chỉ phát các động tác của phần mình — trống ngắt quãng trên bus trống, bass ngắt quãng trên track bass — trong khi bàn trộn hiển thị một dải kênh cho mỗi phiên bản. Trình chỉnh sửa cũng được thiết kế lại trong quá trình này.","changelog.d40fc08c53e8":"<strong>Vai trò.</strong> Mỗi phiên bản plugin nhận một vai trò — cả vòng lặp, trống (hoặc một món trong bộ trống), bass, giai điệu, giai điệu đối, hợp âm, giọng hát, FX hoặc tag nhà sản xuất — từ dải kênh của nó hoặc từ bảng Vai trò &amp; liên kết, kể cả vai trò của phiên bản khác từ bất kỳ cửa sổ nào. Hai phiên bản cùng loại được đánh số (&quot;Giai điệu 2&quot;) và dùng chung một làn. Một phần mà kế hoạch viết cho một vai trò không ai nhận sẽ được đánh dấu trên bản đồ là không được phát ở đâu cả.","changelog.bfed3623cf95":"<strong>Nhạc trưởng.</strong> Phiên bản đầu tiên trên một kênh làm nhạc trưởng: nó lập kế hoạch, và mọi phiên bản khác nhận dữ liệu đầu vào cùng mã băm của nó — không bao giờ là âm thanh — dựng lại đúng kế hoạch đó và báo lại. Một kế hoạch được thay đổi ở bất kỳ cửa sổ nào sẽ được gửi đến nhạc trưởng và đến được tất cả. Khi nhạc trưởng rời đi, phiên bản kế tiếp nhận lấy đũa chỉ huy trong vòng một giây và tiếp tục bản nhạc.","changelog.d186a7625d16":"<strong>Khớp đến từng sample.</strong> Mọi phiên bản đặt mọi cạnh động tác trên cùng một sample, bất kể track của nó chạy với kích thước khối nào; một động tác bộ trống phát trên bus trống được chia qua các dải tần của bus đó đúng như bản nhạc chỉ có một phiên bản sẽ phát.","changelog.0d92b38aa91d":"<strong>Đèn liên kết và bảng Vai trò &amp; liên kết.</strong> Xanh lá: các phiên bản dùng chung bộ nhớ của DAW này. Hổ phách: host đặt mỗi plugin trong một tiến trình riêng (sandbox của Bitwig, cầu nối của Reaper, cầu nối của FL, trình chạy AU của macOS), và thay vào đó các phiên bản gặp nhau qua một tệp nhỏ chỉ chủ sở hữu mới truy cập được — được nói rõ, không giấu đi. Đỏ: một phiên bản không phát kế hoạch của nhạc trưởng, kèm <strong>Gửi lại kế hoạch</strong>. Bốn kênh, A–D, giữ hai dự án trong cùng một DAW tách biệt nhau; một kênh đang phát kế hoạch của dự án khác sẽ báo điều đó và đề xuất kênh kế tiếp, hoặc đi theo kế hoạch đó.","changelog.c4f20b079ad4":"<strong>Bàn trộn v2</strong>: mỗi phiên bản một dải kênh, theo thứ tự vai trò, với đèn báo, núm bộ lọc, đồng hồ VU và fader riêng gắn với những gì luồng âm thanh của phiên bản đó thực sự áp dụng; dải kênh của phiên bản này được viền nổi bật, đũa chỉ huy của nhạc trưởng sáng đèn.","changelog.ad55bbaf935b":"<strong>Diện mạo mới.</strong> Một trình chỉnh sửa tối hơn, dịu mắt hơn: mọi điều khiển trên thanh trên cùng có cùng chiều cao, viền và nền; ô tìm kiếm có biểu tượng riêng; bộ chọn chế độ được vẽ riêng; huy hiệu đồng hồ được tô màu thay vì viền; bản đồ trống được vẽ như bóng mờ của một dòng thời gian; và bàn trộn gồm ba mô-đun — liên kết, một khay dải kênh lõm xuống với bảng tên, và phần master với nút Tạo rộng hết chiều ngang.","changelog.c624ea467282":"<strong>Mặc định là giao diện tối.</strong> Trình chỉnh sửa mở ở giao diện tối bất kể thiết lập của hệ điều hành; <em>Hệ thống</em> và <em>Sáng</em> vẫn có trong phần cài đặt, và giao diện bạn chọn sẽ được ghi nhớ.","changelog.14fe50ad6168":"<strong>Mọi thứ đều vừa vặn, trong mọi ngôn ngữ.</strong> Không nhãn nào tràn ra khỏi khung — tên vai trò dài được xuống dòng trên bảng tên, tên đoạn dài trên bản đồ được cắt bằng dấu ba chấm thay vì bị ép chặt — và trình chỉnh sửa không bao giờ cuộn ngang, kể cả với những cửa sổ hẹp hơn mức bất kỳ host nào nên cấp (một host ở tỷ lệ hiển thị 150 % chỉ cấp cho nó 930 pixel). Thước của bản đồ giãn cách các con số theo độ rộng đo được, các làn co lại thêm trên bản đồ thấp để vẫn hiển thị được cả phiên làm việc, và tên làn có đủ chỗ cần thiết.","changelog.6d85908ca753":"<strong>Cái tên, chỉ một lần.</strong> Mọi định dạng đều báo đúng &quot;Freally Unloop&quot;, và không gì bên cạnh lặp lại nó, nên thanh tiêu đề của host không bao giờ ghi tên hai lần.","changelog.696a4fb40d61":"<strong>Một host có thể bị sập khi đóng một Unloop vừa mới mở</strong> — một lần quét plugin nhanh, một trình xác thực, một dự án bị đóng khi vẫn đang tải. Luồng làm việc nền của framework plugin, dùng chung cho mọi phiên bản, dừng hẳn khi gặp công việc do một phiên bản đã đóng để lại, và phiên bản tiếp theo bị đóng sẽ làm sập host. Unloop không còn giao việc gì cho nó nữa: mỗi phiên bản tự làm việc của mình trên một luồng riêng.","changelog.107aa869557c":"<span class=\"release__meta\"><span class=\"release__ver\">v0.3.0</span><time class=\"release__date\" datetime=\"2026-09-26\">2026-09-26</time></span><span class=\"release__title\">M: Khoảnh khắc kỳ diệu</span>","changelog.edddef519a58":"Một Unloop trên một beat đang lặp giờ đã trình diễn trực tiếp cả bản nhạc: chọn một nghệ sĩ, nhà sản xuất hoặc thể loại, nhấn Tạo, nhấn phát trong DAW, và vòng lặp của bạn trở thành một bài hát đã phối khớp nhịp với host — các phần ngắt đi rồi quay lại, quét bộ lọc, dâng lắp bắp, dừng băng — không tiếng click và không thêm độ trễ, trong khi bản đồ và bàn trộn chuyển động theo.","changelog.c542a3d7af1e":"<strong>Trình diễn trực tiếp (chế độ Một vòng lặp).</strong> Một phiên bản plugin chia vòng lặp của bạn thành ba dải tần — trầm (dưới 120 Hz), trung và cao (trên 4 kHz), bằng bộ chia Linkwitz–Riley cộng lại vẫn phẳng — và phát kế hoạch trên chúng: mỗi dải vào và ra đúng chỗ bản nhạc định, còn các động tác viết cho cả vòng lặp thì tác động lên toàn bộ vòng lặp. Tệp vòng lặp của bạn không hề thay đổi.","changelog.f209a2fc6b77":"<strong>Những động tác đầu tiên bạn nghe được</strong>: tắt tiếng, bật tiếng, ngắt quãng và cắt; quét bộ lọc (thông thấp hoặc thông cao, tần số cắt chính xác ở mọi tick, uốn theo đường cong của kế hoạch); dâng lắp bắp (phách ngay trước đó, được kích lại ngày càng nhanh, dâng dần lên); và dừng băng (vòng lặp chậm dần đến khi dừng hẳn ở ranh giới). Mọi cạnh đều là một đường dốc mềm (5 ms), được kiểm tra tiếng click ở mức −60 dB dưới âm nhạc. Phần còn lại của bộ động tác có trên bản đồ, được đánh dấu phiên bản mà nó sẽ có.","changelog.079fb6a04db0":"<strong>Khớp nhịp với host, dù host phát theo cách nào.</strong> Đồng hồ bài hát đặt bản nhạc lên dòng thời gian của bạn từ một ô nhịp bạn chọn; đồng hồ vòng lặp đếm số vòng lặp quay — chế độ pattern của FL Studio, một vùng lặp, chế độ xem session của Ableton — nên 200 vòng lặp đúng là 200 vòng lặp. <em>Tự động</em> chọn một trong hai cho mỗi lần phát và giải thích lý do trên huy hiệu đồng hồ. Khi đổi nhịp độ, mọi động tác vẫn giữ đúng ô nhịp của nó.","changelog.dd9565bb9638":"<strong>Host làm chủ nhịp độ.</strong> Nhãn nhịp độ hiển thị BPM của DAW và cho biết nó có hợp với cái tên bạn đã chọn hay không — tính cả nửa nhịp và gấp đôi nhịp, kèm tỷ lệ — và khi không hợp, hiển thị nhịp độ điển hình và nhịp độ gần nhất trong khoảng để bạn sao chép và tự đặt. Unloop không bao giờ thay đổi nhịp độ của DAW.","changelog.43c245c305f5":"<strong>Tìm kiếm</strong> trên cả 2.413 cái tên, bỏ qua lỗi gõ như cách tìm kiếm của Freally MIDI Master (&quot;metro bumin&quot; tìm ra Metro Boomin), mỗi dòng cho biết đó là gì và bao nhiêu phần là của riêng nó; các lựa chọn gần đây được xếp trước; &quot;Có phải bạn muốn tìm&quot; khi không có kết quả khớp. <strong>Thẻ mô hình</strong> trước khi bạn nhấn bất cứ thứ gì, kèm bản xem trước cấu trúc của một chế độ trên bản đồ trống. <strong>Bộ chọn chế độ</strong> (có <em>Bất kỳ</em>) và <strong>nhãn hạt giống</strong> — sao chép nó, hoặc dán một hạt giống vào để lấy lại đúng bản nhạc đó.","changelog.c4d42bdbfb75":"<strong>Bản đồ phối khí</strong>: các đoạn, ba làn dải tần với đoạn mờ dần của từng clip được vẽ đúng như cách âm thanh được định hình, một ký hiệu cho mỗi động tác, đường cong năng lượng, thước ô nhịp kèm phút và giây, và đầu phát của host; một động tác bừng sáng trên các làn của nó khi đang phát. Bản đồ hiện dần lên khi có bản nhạc mới (nhấn một phím hoặc nhấp chuột để bỏ qua; hiện ngay lập tức khi bật chế độ giảm chuyển động).","changelog.b9acf1dcbf7e":"<strong>Bàn trộn</strong>: một dải kênh có đèn báo, fader và núm bộ lọc hiển thị những gì luồng âm thanh thực sự áp dụng, một đồng hồ VU với quán tính kim như thật, và phần master — Tạo, Tạo lại, bộ đếm băng và hạt giống. Khi không có gì cho Unloop biết vòng lặp của bạn dài bao nhiêu, nó sẽ hỏi một lần (2, 4, 8 hoặc 16 ô nhịp) và không bao giờ chặn nút Tạo.","changelog.7e08eeb2a0b2":"<strong>Dự án ghi nhớ.</strong> Cái tên, chế độ, hạt giống, độ dài vòng lặp và phiên làm việc được lưu trong dự án DAW của bạn; mở lại dự án sẽ tạo lại đúng bản nhạc đó — cùng kế hoạch, khớp đến mã băm — và khi độ dài vòng lặp hay số chỉ nhịp thay đổi (câu trả lời của bạn, vùng lặp của DAW), kế hoạch sẽ được lập lại cho phù hợp.","changelog.cac34fa81c8b":"<strong>Mọi tên mô hình, thể loại và chế độ đều được kiểm tra với các phông chữ Noto đi kèm</strong>, như các bản dịch đã được kiểm tra, nên không cái tên nào trong danh sách phải chuyển sang phông chữ hệ thống hay hiện ô vuông thiếu ký tự.","changelog.7962b5beebac":"<strong>Bypass</strong> làm mờ dần cả phần trình diễn <em>lẫn</em> mức chỉnh Output cùng lúc, rồi cho âm thanh của bạn đi qua nguyên vẹn; các đồng hồ đo đọc đúng những gì thực sự ra khỏi plugin, sau mức chỉnh.","changelog.ec1231a741d1":"<span class=\"release__meta\"><span class=\"release__ver\">v0.2.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">P: Bộ lập kế hoạch</span>","changelog.475985e8de84":"Bất kỳ cái tên nào trong 2.413 cái tên giờ đều trở thành một kế hoạch phối khí tất định. Chưa có gì phát nó — lần trình diễn trực tiếp đầu tiên là <code>v0.3.0</code> — nhưng mọi quyết định một bản nhạc cần đều được đưa ra ở đây, trên lưới, trước khi một sample nào được phát.","changelog.79a17b028e4f":"<strong>Bộ lập kế hoạch.</strong> Một cái tên, một chế độ, phiên làm việc và một hạt giống trở thành trọn một bản nhạc: cấu trúc bài hát, độ dài từng đoạn trên lưới câu nhạc 4/8/16 ô nhịp, những phần nào chơi trong mỗi đoạn và chơi thế nào (chỉ hi-hat, qua bộ lọc, mờ dần, nửa nhịp), mọi động tác được đặt chính xác đến từng tick — ngắt quãng, cắt, dâng lắp bắp, cuộn trống, quét, dừng băng, đổi beat, hiệu ứng chuyển đoạn, điểm nhấn tai, tag của nhà sản xuất — và đường cong năng lượng theo từng ô nhịp. Cùng đầu vào cho ra cùng kế hoạch, khớp từng byte, được niêm phong bằng mã băm kế hoạch BLAKE3. Nó lập kế hoạch cho một bản nhạc dài ba phút trong chưa đến một mili giây.","changelog.989666ca013f":"<strong>Mỗi thể loại được phối theo nhiều cách.</strong> Các chế độ — bản radio, bản mixtape, bản club/DJ, đổi beat, tối giản, tinh giản, mở rộng, và các chế độ riêng của từng thể loại (cổ điển, bài tập thể và băng beat cho boom bap; bản chậm và đoạn chuyển cho R&amp;B thập niên 2000; bản giọng hát cho liquid drum &amp; bass). <em>Bất kỳ</em> chọn một chế độ theo trọng số của nó.","changelog.5de91eed2226":"<strong>12 mô hình thể loại đầu tiên</strong>, được soạn từ nghiên cứu phối khí: trap, dark trap, plugg, pluggnb, rage, UK drill, NY drill, boom bap, R&amp;B thập niên 2000, pop thập niên 2020, country-pop và liquid drum &amp; bass — 39 chế độ — cùng mô hình mặc định mà mọi cái tên khác dựa vào.","changelog.a883b8d3cf75":"<strong>Toàn bộ danh sách tên, đã được nhập.</strong> 2.413 cái tên — 1.507 nghệ sĩ, 833 nhà sản xuất, 73 thể loại — từ bộ dữ liệu của Freally MIDI Master ở bản phát hành đã ghim, kèm tên gọi khác, thời kỳ, thể loại, quan hệ kế thừa, nhịp độ và cấu trúc bài hát. Việc nhập tái tạo được chính xác đến từng byte, và mỗi trường không được đọc đều có lời giải thích lý do.","changelog.8f2f1aef5133":"<strong>Một huy hiệu trung thực trên mỗi cái tên.</strong> <em>Chủ lực</em> (có mô hình riêng), <em>tiêu chuẩn</em> (dùng cấu trúc bài hát hoặc độ dài đoạn của riêng nó — 1.157 cái tên) hoặc <em>kế thừa</em> (của thể loại nó — 1.244 cái tên), được suy ra từ những gì bộ lập kế hoạch thực sự đã dùng.","changelog.33b91bcddab0":"<strong>Tạo lại một thứ.</strong> Một kế hoạch có thể chỉ rút lại các điểm nhấn tai, hoặc các phần của một đoạn, còn mọi thứ khác vẫn giữ y nguyên.","changelog.fc97f471bb4b":"<strong>Sẵn sàng cho chế độ Một vòng lặp.</strong> Mỗi động tác cho biết một phiên bản plugin duy nhất, khi chia một vòng lặp thành ba dải tần, sẽ xử lý nó thế nào, và khi một dải tần phải thay thế cho một phần không tách riêng được, kế hoạch sẽ nói rõ điều đó.","changelog.cba5495f6089":"<strong>Thẻ mô hình</strong>: các chế độ, cấu trúc, độ dài đoạn, động tác đặc trưng, năng lượng điển hình, nhịp độ, quan hệ kế thừa và nguồn gốc — được tính từ những gì bộ lập kế hoạch trình diễn, kèm tuyên bố miễn trừ trách nhiệm.","changelog.88d2b1cd382c":"<strong><code>unloopc</code>, trình biên dịch bộ dữ liệu</strong> — <code>validate</code>, <code>stats</code>, <code>coverage</code>, <code>distinct</code>, <code>card</code>, <code>plan</code>, <code>import-roster</code>, <code>schema</code> — cùng <code>npm run dataset:*</code>. Lược đồ mô hình và tệp từ vựng được sinh ra từ các kiểu Rust.","changelog.b582568bbaf2":"<strong>Cổng kiểm tra</strong>: việc nhập danh sách tên, lược đồ và mọi mô hình (<code>ci:local</code> và <code>ci:linux</code>); mọi khóa được soạn đều được bộ lập kế hoạch đọc — mỗi khóa được chứng minh là làm thay đổi kế hoạch khi nó thay đổi; mọi chuỗi được soạn đều được phân tích theo bộ từ vựng của nó; từ hai chế độ khác biệt trở lên cho mỗi thể loại; 24 kế hoạch chuẩn; toàn bộ danh sách tên được lập kế hoạch hai lần và so sánh; ngân sách lập kế hoạch 50 ms ở phân vị thứ 95; và mọi vị trí <code>unsafe</code> trong plugin đều phải nằm trong danh sách đã ghi lại. Mỗi cổng kiểm tra đều được chứng kiến thất bại trước khi được tin dùng.","changelog.c83336253c11":"<strong>Ghi chú dưới nút Tạo</strong> giờ cho biết tính năng này có trong bản dựng kế tiếp — bộ lập kế hoạch mà nó chờ đã có ở đây, và nút được nối dây trong <code>v0.3.0</code> — bằng cả 18 ngôn ngữ.","changelog.5a7a1b20ab13":"<strong>Ứng dụng độc lập trên màn hình có tỷ lệ hiển thị (Windows).</strong> Trang bị lệch bên trong cửa sổ, bị cắt ở cạnh phải và cạnh dưới, và trượt ra sau khung khi kéo cửa sổ: tiến trình không nhận biết DPI, nên Windows kéo giãn cửa sổ trong khi web view vẽ theo pixel thật. Giờ đây ứng dụng độc lập khai báo nhận biết DPI theo từng màn hình trước khi có bất kỳ cửa sổ nào.","changelog.df00e0d65bc5":"<strong>Ứng dụng độc lập mở ở đúng kích thước của plugin.</strong> Nó truyền tỷ lệ hiển thị cho nih-plug dưới dạng <code>--dpi-scale</code> (một <code>--dpi-scale</code> được chỉ định rõ vẫn được ưu tiên), nên nó mở lớn đúng bằng chính trình chỉnh sửa đó trong một host.","changelog.0e3c3179efba":"<span class=\"release__meta\"><span class=\"release__ver\">v0.1.0</span><time class=\"release__date\" datetime=\"2026-09-24\">2026-09-24</time></span><span class=\"release__title\">F: Nền móng</span>","changelog.42f5ee22d43e":"Sản phẩm rỗng làm nền cho mọi nấc sau: nó tải được, cho âm thanh đi qua nguyên vẹn, mở trình chỉnh sửa, và mọi cổng kiểm tra chất lượng đều chạy.","changelog.c794a76c2618":"<strong>Plugin, ở mọi định dạng từ một tệp nhị phân.</strong> Một plugin CLAP dựng bằng nih-plug với các điểm vào VST3 và AUv2 do <code>clap-wrapper</code> tạo ra (sạch về giấy phép: không dùng binding VST3 theo GPL), cùng ứng dụng độc lập. Stereo hoặc mono, cho âm thanh đi qua, độ trễ bằng không, trạng thái lưu có đánh phiên bản và từ chối mọi thứ không đọc được thay vì làm sập host, một công tắc <strong>Bypass</strong> cho host và một mức chỉnh <strong>Output</strong> (−24 đến +6 dB, được làm mượt).","changelog.6f91cc8aeb3f":"<strong>Khung trình chỉnh sửa.</strong> Trình chỉnh sửa React trong bộ chuyển đổi webview dùng chung của Freally, được phục vụ từ bên trong tệp nhị phân dưới một chính sách bảo mật nội dung (Content Security Policy) nghiêm ngặt, với một cầu nối có kiểu đến plugin (yêu cầu/phản hồi cùng các sự kiện được thăm dò) mà các kiểu TypeScript của nó được sinh ra từ các kiểu Rust.","changelog.e6f8feb48be4":"<strong>Thanh tiêu đề Freally.</strong> Tên sản phẩm dạng 3D, xoay ngược quanh trục Y, dừng lại, rồi xoay trở lại — như trong Freally MIDI Master và Freally Oscillate, được làm lớn hơn để dễ thấy vòng xoay; đứng yên khi bật chế độ giảm chuyển động.","changelog.f556ccffa36f":"<strong>Thỏa thuận cấp phép</strong> (<code>EULA.md</code>) và cổng kiểm tra của nó: Unloop yêu cầu bạn chấp nhận nó ở lần mở đầu tiên và không hoạt động cho đến khi bạn đồng ý. Một plugin chưa hoạt động cho âm thanh của bạn đi qua nguyên vẹn — không thiết lập nào từ host hay từ dự án đã lưu, kể cả mức chỉnh Output, làm thay đổi âm thanh trước khi bạn đồng ý. Việc chấp nhận hay từ chối ở một phiên bản plugin đến được mọi phiên bản đang mở ngay lập tức, và một lần từ chối không lưu được sẽ được báo rõ thay vì để phiên làm việc sau mở ra như thể bạn đã đồng ý.","changelog.b3fe519bf775":"<strong><code>THIRD-PARTY-NOTICES.md</code></strong>, được sinh ra từ những gì thực sự được phát hành — mọi crate trong plugin và ứng dụng độc lập trên mọi hệ điều hành, các gói của trình chỉnh sửa và các phông chữ, kèm giấy phép và chủ sở hữu bản quyền của chúng — và có trong mọi gói phát hành cùng giấy phép của phông chữ (<code>OFL-Noto.txt</code>).","changelog.565020242597":"<strong>Token thiết kế và giao diện</strong> — tối, sáng và theo hệ thống — với độ tương phản WCAG 2.1 AA được kiểm tra ở cả hai; phông chữ Noto được đóng gói sẵn cho cả 18 ngôn ngữ.","changelog.7ddbeff39e12":"<strong>18 ngôn ngữ</strong> trong trình chỉnh sửa, với một cổng kiểm tra giữ mọi bộ chuỗi luôn đồng bộ.","changelog.6ad657e4e2ad":"<strong>Theo dõi chẩn đoán</strong> (<code>UNLOOP_TRACE=all</code>, ghi vào một tệp nhật ký) cho những lỗi chỉ xảy ra bên trong host.","changelog.594511701ab8":"<strong>Biểu tượng</strong> được tạo từ một bản gốc biểu tượng duy nhất cho Windows, macOS, Linux và trang tài liệu.","changelog.3ad9c9b08c97":"<strong>Cổng kiểm tra chất lượng</strong>, trong <code>npm run ci:local</code> (Windows) và <code>npm run ci:linux</code> (Docker Desktop): định dạng mã, lint, kiểm tra kiểu, clippy với <code>std::net</code> bị cấm, kiểm thử đơn vị và Playwright, một bài kiểm thử đếm số lần cấp phát trên luồng âm thanh, cổng kiểm tra phụ thuộc không AI/không mạng/không đo lường từ xa, chính sách giấy phép và cảnh báo bảo mật, cổng kiểm tra tệp thông báo được sinh ra, cổng kiểm tra mã dùng chung và độ lệch binding, cổng không có bản tải xuống trước 1.0 cho trang tài liệu, cùng clap-validator và pluginval (độ nghiêm ngặt 10). Mỗi cổng kiểm tra đều được chứng kiến thất bại trước khi được tin dùng.","changelog.29509f5c50ce":"<strong>Công cụ phát hành</strong>: <code>npm run release:bundle</code> và một quy trình phát hành chỉ chạy theo tag, không giữ token ghi hay token kho riêng tư nào trong khi chạy mã dựng của bên thứ ba, và kiểm tra mỗi gói nén có thực sự là zip hoặc gzip trước khi công bố.","changelog.361aee95901b":"Khung trang tài liệu cùng chiếc thang phiên bản công khai.","changelog.388399ae707a":"Cầu nối của trình chỉnh sửa chỉ trả lời các yêu cầu JSON <code>POST</code> của chính trình chỉnh sửa: một trang không phải của Unloop — một liên kết hay tệp được thả vào cửa sổ — không thể gọi nó cũng không đọc được câu trả lời, và việc thả vào không còn làm trình chỉnh sửa chuyển trang nữa.","changelog.1f976b647d80":"Plugin bản phát hành không mở cổng gỡ lỗi DevTools nào (móc kiểm thử của Freally MIDI Master, giờ nằm sau một tính năng mà Unloop dựng mà không bật), và bước kiểm tra gói từ chối một tệp nhị phân có thể mở cổng đó, hoặc một tệp không được dựng từ mã nguồn đã ghim.","changelog.f65776baedfa":"Theo dõi chẩn đoán không còn có thể làm sập host nếu cửa sổ console của nó đã mất.","changelog.2fedafc14be7":"<strong>Linux: trình chỉnh sửa không giao tiếp được với plugin.</strong> Webview gửi mọi yêu cầu qua cầu nối với phần thân rỗng, nên thỏa thuận cấp phép không bao giờ chấp nhận được. Giờ phần thân yêu cầu đã đến nơi (WebKitGTK 2.40 trở lên).","changelog.55bda2d0ead3":"Ứng dụng độc lập không còn từ chối khởi động khi được truyền <code>-p &lt;period&gt;</code>.","changelog.bf6b0c2f06b4":"<strong>Linux: host quét plugin bằng cách tải rồi gỡ chúng không còn bị sập vài giây sau đó.</strong> WebKitGTK của trình chỉnh sửa mang theo các luồng JavaScriptCore; thư viện plugin giờ được giữ nạp cho đến khi host thoát (các bài kiểm thử quét của clap-validator đã phát hiện lỗi này).","changelog.f95b9de4af46":"<strong>Linux: đóng trình chỉnh sửa quá nhanh không còn làm host thoát</strong> — hai bản sửa trong bộ chuyển đổi webview dùng chung của Freally (một bẫy lỗi X trên luồng GTK của nó, và thao tác đóng có chờ web view biến mất hẳn). pluginval ở độ nghiêm ngặt 10 giờ đã vượt qua trên Linux, kể cả các bài kiểm thử trình chỉnh sửa.","changelog.51862fa2d198":"Đã sửa ở thượng nguồn (trong bản fork nih-plug dùng chung, được sử dụng qua <code>shared-v1</code> của Freally MIDI Master)","changelog.89bea0569ab2":"Host CLAP giờ được thông báo rằng các giá trị thông số đã thay đổi sau khi một dự án được tải (clap-validator <code>state-reproducibility-*</code>).","changelog.26edfb636bce":"Mở hoặc đóng trình chỉnh sửa không còn giữ một khóa mà chính quá trình khởi động của trình chỉnh sửa có thể vào lại — một tình trạng khóa chết trên luồng chính của host (pluginval <code>Editor Automation</code>).","changelog.e6463781d61f":"<code>rtrb</code> được nâng lên 0.3.5, xử lý RUSTSEC-2026-0274 (lỗi dùng bộ nhớ sau khi giải phóng) tận gốc thay vì bỏ qua nó.","changelog.d9577706c4ec":"Host: việc tải trong FL Studio, Ableton Live và Reaper được chứng minh bằng tay, không phải bằng CI, và các dòng đó trong ma trận host vẫn chưa được thử ở nấc này; các trình xác thực chứng minh plugin được dựng đúng chuẩn, và ứng dụng độc lập đã được chạy thử.","changelog.edf3e5f9658b":"AU đã được dựng và đóng gói nhưng chưa được kiểm chứng: chưa có máy Mac nào tải nó. Trình chỉnh sửa trên Linux đã được dựng và xác thực trong container nhưng chưa được dùng trong một phiên Linux thật.","changelog.c95891622d38":"Bộ chuyển đổi webview dùng chung lưu dữ liệu trình duyệt trong một thư mục mang tên Freally MIDI Master cho đến khi bộ chuyển đổi có thể tự đặt tên riêng (có trong lộ trình)."};
